var e=(e,t)=>({pl:e,en:t}),t=[`length`,`span`,`mtow`,`payload`,`warhead`,`speed`,`cruise`,`range`,`endurance`,`ceiling`,`engine`,`guidance`,`launch`,`cost`],n={length:e(`Długość`,`Length`),span:e(`Rozpiętość / szerokość`,`Wingspan / beam`),mtow:e(`Masa startowa`,`MTOW`),payload:e(`Ładunek użyteczny`,`Payload`),warhead:e(`Głowica`,`Warhead`),speed:e(`Prędkość maksymalna`,`Max. speed`),cruise:e(`Prędkość przelotowa`,`Cruise speed`),range:e(`Zasięg`,`Range`),endurance:e(`Czas lotu / autonomii`,`Endurance`),ceiling:e(`Pułap`,`Ceiling`),engine:e(`Napęd`,`Powerplant`),guidance:e(`Naprowadzanie`,`Guidance`),launch:e(`Start / odzysk`,`Launch / recovery`),cost:e(`Koszt jednostki`,`Unit cost`)},r=[{id:`mavic3t`,image:`/drones/mavic.jpg`,typeId:`isr-cots`,domain:`air`,theaters:[`ukraine`,`middle-east`,`africa`,`global`],year:`2022–2026`,featured:!0,name:e(`DJI Mavic 3T / 3E`,`DJI Mavic 3T / 3E`),origin:e(`Chiny (DJI)`,`China (DJI)`),operators:e(`obie strony na froncie UA; siły nieregularne na świecie`,`both sides on the UA front; irregular forces worldwide`),role:e(`Rozpoznanie drużynowe i korekta ognia`,`Squad-level ISR and fire adjustment`),note:e(`Najpowszechniejszy zwiadowca taktyczny wojny. Kamera dzienna 4/3″, teleobiektyw i termowizja 640×512. Cywilny sprzęt w roli militarnej: obie strony masowo go kupują, modyfikują anteny i doklejają wzmacniacze. Zasięg fabryczny 8–15 km; z przekaźnikiem bywa dwukrotnie większy.`,`The war’s most common tactical scout. A 4/3″ daylight camera, a telephoto and a 640×512 thermal imager. Civilian kit in a military role: both sides buy it in bulk, swap antennas and add boosters. Factory range 8–15 km; with a relay it can double.`),specs:{length:e(`347 × 283 × 108 mm (rozłożony)`,`347 × 283 × 108 mm (unfolded)`),span:e(`przekątna 380 mm`,`380 mm diagonal`),mtow:e(`920 g (3T)`,`920 g (3T)`),payload:e(`EO/IR, bez ładunku bojowego`,`EO/IR, no warhead`),speed:e(`76 km/h (tryb sport)`,`76 km/h (Sport)`),range:e(`8 km (CE) / 15 km (FCC)`,`8 km (CE) / 15 km (FCC)`),endurance:e(`ok. 45 min`,`about 45 min`),ceiling:e(`6000 m n.p.m.`,`6,000 m AMSL`),engine:e(`4× silnik bezszczotkowy, Li-ion`,`4× brushless motors, Li-ion`),guidance:e(`GNSS + optyka + radio OcuSync`,`GNSS + vision + OcuSync radio`),cost:e(`ok. 4–5 tys. USD (cywilny)`,`about USD 4–5 thousand (civilian)`)}},{id:`fpv10`,image:`/drones/fpv.jpg`,typeId:`fpv-radio`,domain:`air`,theaters:[`ukraine`,`middle-east`,`global`],year:`2023–2026`,featured:!0,name:e(`FPV 10-calowy (klasa)`,`10-inch FPV (class)`),aka:e(`„piechota dronów”`,`“drone infantry”`),origin:e(`Ukraina i Rosja — setki warsztatów`,`Ukraine and Russia — hundreds of workshops`),operators:e(`SZU, SBU, GUR; SZ RF, Rubikon`,`AFU, SBU, HUR; Russian forces, Rubikon`),role:e(`Kamikaze w strefie kontaktu`,`Kamikaze in the contact zone`),note:e(`Rama 10-calowa (około 254 mm między osiami silników) to de facto standard uderzeniowego FPV. Głowica: pocisk PG-7, ładunek odłamkowy albo termobaryczny o masie 0,5–2 kg. Ukraina planowała zakup 4,5 mln sztuk na 2025 r.; w 2026 r. zdolność produkcyjna szacuje się na 7–20 mln, zależnie od pieniędzy. Z przekaźnikiem notowano uderzenia ponad sto kilometrów za linią.`,`A 10-inch frame (about 254 mm motor-to-motor) is the de facto strike-FPV standard. Warhead: a PG-7 round, fragmentation or thermobaric charge of 0.5–2 kg. Ukraine planned 4.5 million units for 2025; 2026 capacity is estimated at 7–20 million, funding permitting. With relays, strikes more than 100 km behind the line have been logged.`),specs:{span:e(`rama 10″ (przekątna ok. 45 cm)`,`10″ frame (diagonal ~45 cm)`),mtow:e(`1,2–2,8 kg z głowicą`,`1.2–2.8 kg with warhead`),warhead:e(`0,5–2,5 kg (PG-7, odłamkowa, TB)`,`0.5–2.5 kg (PG-7, HE-FRAG, TB)`),speed:e(`100–160 km/h`,`100–160 km/h`),range:e(`5–25 km (radio); >100 km z przekaźnikiem`,`5–25 km (radio); >100 km with a relay`),endurance:e(`8–15 min`,`8–15 min`),ceiling:e(`zwykle <500 m AGL`,`usually <500 m AGL`),engine:e(`4× bezszczotkowy, pakiet 6S Li-ion`,`4× brushless, 6S Li-ion pack`),guidance:e(`FPV analog/cyfra, operator w pętli`,`analogue/digital FPV, operator in the loop`),launch:e(`z ręki / z rampy`,`hand / ramp`),cost:e(`400–800 USD`,`USD 400–800`)}},{id:`fpv-fiber`,image:`/drones/fpv.jpg`,typeId:`fpv-fiber`,domain:`air`,theaters:[`ukraine`,`middle-east`],year:`2024–2026`,name:e(`FPV światłowodowe`,`Fibre-optic FPV`),origin:e(`Ukraina i Rosja`,`Ukraine and Russia`),operators:e(`SZU; SZ RF (m.in. Rubikon)`,`AFU; Russian forces (incl. Rubikon)`),role:e(`Atak odporny na WRE`,`EW-proof attack`),note:e(`Zamiast radia — szpula światłowodu z tyłu kadłuba. Zagłuszanie nie odcina sterowania, ale kabel ogranicza manewr i plącze się o drzewa. Do sierpnia 2025 r. ukraińskie MON skodyfikowało ponad 80 takich systemów. Na początku 2026 r. typowy zasięg wynosił 15–25 km; później 40–50 km, a po stronie rosyjskiej pojawiały się relacje o około 65 km na węzły logistyczne.`,`A fibre spool behind the fuselage replaces the radio. Jamming cannot cut the link, but the cable limits manoeuvre and snags on trees. Ukraine’s MoD had codified 80+ systems by August 2025. Early 2026 typical reach 15–25 km; later 40–50 km, with Russian reports of about 65 km against logistics hubs.`),specs:{span:e(`rama 8–10″`,`8–10″ frame`),mtow:e(`1,5–3,2 kg (szpula + głowica)`,`1.5–3.2 kg (spool + warhead)`),warhead:e(`do ok. 2 kg`,`up to ~2 kg`),speed:e(`80–140 km/h`,`80–140 km/h`),range:e(`15–50 km (UA); do 65 km (RF, 2026)`,`15–50 km (UA); up to 65 km (RU, 2026)`),endurance:e(`ograniczony masą szpuli`,`limited by spool mass`),engine:e(`4× bezszczotkowy`,`4× brushless`),guidance:e(`światłowód, operator w pętli`,`fibre, operator in the loop`),cost:e(`800–2500 USD`,`USD 800–2,500`)}},{id:`vampire`,image:`/drones/vampire2.jpg`,typeId:`bomber`,domain:`air`,theaters:[`ukraine`],year:`2023–2026`,featured:!0,name:e(`Vampire (SkyFall)`,`Vampire (SkyFall)`),aka:e(`Baba Jaga`,`Baba Yaga`),origin:e(`Ukraina (SkyFall)`,`Ukraine (SkyFall)`),operators:e(`Siły Zbrojne Ukrainy`,`Armed Forces of Ukraine`),role:e(`Nocny zrzut min i moździerzy`,`Night drops of mines and mortar rounds`),tidbit:e(`Rosjanie całą klasę takich maszyn nazywają „Babą Jagą” — od wiedźmy z bajki, która lata w moździerzu.`,`Russians call the whole class “Baba Yaga” — after the fairy-tale witch who flies in a mortar.`),note:e(`Sześciowirnikowiec wielokrotnego użytku firmy SkyFall — największego ukraińskiego producenta dronów. Zrzuca miny TM-62 i pociski moździerzowe 82/120 mm, zwykle nocą, z termowizją. Jeden egzemplarz odbywa dziesiątki wylotów. Koszt: 8–10 tys. dolarów. Wersja bez chińskich części trafiła na amerykańską listę Blue UAS. SkyFall robi też FPV Shrike i interceptor P1-SUN.`,`A reusable hexacopter from SkyFall — Ukraine’s largest drone maker. It drops TM-62 mines and 82/120 mm mortar rounds, usually at night, with thermal sights. Tens of sorties per airframe. Cost: USD 8–10 thousand. A non-Chinese version is on the US Blue UAS list. SkyFall also builds the Shrike FPV and the P1-SUN interceptor.`),specs:{span:e(`hexakopter, rozstaw ramion ok. 1,5–2 m`,`hexacopter, arm span ~1.5–2 m`),mtow:e(`ok. 15–25 kg`,`about 15–25 kg`),payload:e(`do 15 kg`,`up to 15 kg`),speed:e(`ok. 40–60 km/h z ładunkiem`,`about 40–60 km/h laden`),range:e(`do 20 km`,`up to 20 km`),endurance:e(`25–40 min`,`25–40 min`),ceiling:e(`zwykle <1000 m`,`usually <1,000 m`),engine:e(`6× bezszczotkowy, Li-ion`,`6× brushless, Li-ion`),guidance:e(`radio + FPV/termowizja`,`radio + FPV/thermal`),launch:e(`z ziemi, wielorazowy`,`from the ground, reusable`),cost:e(`8–10 tys. USD`,`USD 8–10 thousand`)}},{id:`leleka`,image:`/drones/leleka.jpg`,typeId:`isr-tactical`,domain:`air`,theaters:[`ukraine`],year:`2021–2026`,name:e(`Leleka-100`,`Leleka-100`),aka:e(`Stork-100`,`Stork-100`),origin:e(`Ukraina (DeViRo)`,`Ukraine (DeViRo)`),operators:e(`Siły Zbrojne Ukrainy`,`Armed Forces of Ukraine`),role:e(`Krajowy zwiadowca artyleryjski`,`National artillery scout`),note:e(`Podstawowy ukraiński stałopłat rozpoznawczy szczebla brygady. Kadłub z kevlaru, włókna szklanego i węglowego, śmigło pchające. Wersja LR wydłuża łączność do ok. 90 km. Start z katapulty gumowej, odzysk na spadochronie albo „na brzuchu”.`,`Ukraine’s baseline brigade-level reconnaissance monoplane. Kevlar, glass and carbon airframe, pusher propeller. The LR version stretches the datalink to about 90 km. Bungee-catapult launch, parachute or belly recovery.`),specs:{length:e(`1,13 m`,`1.13 m`),span:e(`1,98 m`,`1.98 m`),mtow:e(`5,5 kg`,`5.5 kg`),payload:e(`EO/IR (ok. 0,8–1 kg)`,`EO/IR (~0.8–1 kg)`),speed:e(`120–140 km/h`,`120–140 km/h`),cruise:e(`ok. 60–70 km/h`,`about 60–70 km/h`),range:e(`łączność 45 km; trasa do 100–340 km`,`datalink 45 km; route up to 100–340 km`),endurance:e(`2–2,5 h (LR do 4 h)`,`2–2.5 h (LR up to 4 h)`),ceiling:e(`1500 m`,`1,500 m`),engine:e(`silnik elektryczny, śmigło pchające`,`electric motor, pusher propeller`),guidance:e(`autopilot INS/GNSS, radio szyfrowane`,`INS/GNSS autopilot, encrypted radio`),launch:e(`katapulta / z ręki; spadochron`,`catapult / hand; parachute`)}},{id:`furia`,image:`/drones/shark.jpg`,typeId:`isr-tactical`,domain:`air`,theaters:[`ukraine`],year:`2020–2026`,name:e(`A1-CM Furia`,`A1-CM Furia`),origin:e(`Ukraina (Athlon Avia)`,`Ukraine (Athlon Avia)`),operators:e(`Siły Zbrojne Ukrainy`,`Armed Forces of Ukraine`),role:e(`Korekta artylerii i rakiet`,`Artillery and rocket adjustment`),note:e(`Skrzydło latające z kadłubem z włókna szklanego. W służbie od 2020 r.; ok. 300 kompleksów. Używana do korekty ognia lufowego i rakietowego. Zasięg od stanowiska kierowania ok. 50 km, trasa do 200 km.`,`A flying-wing glass-fibre airframe. In service since 2020; about 300 complexes. Used to adjust tube and rocket artillery. About 50 km from the control post, route up to 200 km.`),specs:{length:e(`0,90 m`,`0.90 m`),span:e(`2,00 m`,`2.00 m`),mtow:e(`5,5–6 kg`,`5.5–6 kg`),payload:e(`EO/IR, ok. 1–1,5 kg`,`EO/IR, about 1–1.5 kg`),speed:e(`do 130 km/h`,`up to 130 km/h`),cruise:e(`ok. 65 km/h`,`about 65 km/h`),range:e(`łączność 50 km; trasa do 200 km`,`datalink 50 km; route up to 200 km`),endurance:e(`ok. 3 h`,`about 3 h`),ceiling:e(`1200–2000 m`,`1,200–2,000 m`),engine:e(`elektryczny`,`electric`),guidance:e(`INS/GNSS + radio`,`INS/GNSS + radio`),launch:e(`katapulta; spadochron`,`catapult; parachute`)}},{id:`shark`,image:`/drones/shark.jpg`,typeId:`isr-tactical`,domain:`air`,theaters:[`ukraine`,`nato`],year:`2023–2026`,name:e(`SHARK`,`SHARK`),origin:e(`Ukraina (Ukrspecsystems)`,`Ukraine (Ukrspecsystems)`),operators:e(`SZU; linia w Wielkiej Brytanii`,`AFU; a line in the United Kingdom`),role:e(`ISR taktyczny z 30× zoomem`,`Tactical ISR with 30× zoom`),note:e(`Układ belka–dwa wysięgniki, kamera z 30-krotnym zoomem optycznym (łącznie 90×). Pozwala obserwować pozycje z 5 km. Linia produkcyjna w Wielkiej Brytanii — cel: do 1000 sztuk miesięcznie na potrzeby Ukrainy.`,`Pod-and-twin-boom layout, a camera with 30× optical zoom (90× total). Can watch positions from 5 km. A UK production line — target: up to 1,000 units a month for Ukraine.`),specs:{length:e(`1,65 m`,`1.65 m`),span:e(`3,40 m`,`3.40 m`),mtow:e(`12,5–13,5 kg`,`12.5–13.5 kg`),payload:e(`do 3,5 kg (USG-231 / 231T)`,`up to 3.5 kg (USG-231 / 231T)`),speed:e(`130–150 km/h`,`130–150 km/h`),cruise:e(`75–80 km/h`,`75–80 km/h`),range:e(`łączność 80 km; trasa ok. 300 km`,`datalink 80 km; route ~300 km`),endurance:e(`4 h`,`4 h`),ceiling:e(`3000 m`,`3,000 m`),engine:e(`spalinowy / elektryczny (zależnie od serii)`,`ICE / electric (by series)`),guidance:e(`szyfrowane radio, INS/GNSS`,`encrypted radio, INS/GNSS`),launch:e(`katapulta; spadochron`,`catapult; parachute`)}},{id:`pd2`,image:`/drones/shark.jpg`,typeId:`isr-tactical`,domain:`air`,theaters:[`ukraine`],year:`2022–2026`,name:e(`PD-2`,`PD-2`),origin:e(`Ukraina (Ukrspecsystems)`,`Ukraine (Ukrspecsystems)`),operators:e(`Siły Zbrojne Ukrainy`,`Armed Forces of Ukraine`),role:e(`ISR operacyjny, wariant VTOL`,`Operational ISR, VTOL variant`),note:e(`Większy wariant z tej samej rodziny co SHARK. Bywa z podwoziem albo z modułem pionowego startu. Łączność ponad 180 km, czas lotu 8–10 godzin. Może zabrać ładunek uderzeniowy do 11 kg — na froncie służy jednak przede wszystkim jako zwiadowca.`,`A larger member of the same family as SHARK. Undercarriage or a vertical-take-off module. Datalink beyond 180 km, 8–10 hours in the air. Optional strike load up to 11 kg — at the front it is used first as a scout.`),specs:{length:e(`2,85 m`,`2.85 m`),span:e(`5,00 m`,`5.00 m`),mtow:e(`55 kg`,`55 kg`),payload:e(`10–11 kg (ISR, opcjonalnie uderzenie)`,`10–11 kg (ISR, optional strike)`),speed:e(`140 km/h`,`140 km/h`),cruise:e(`100 km/h`,`100 km/h`),range:e(`łączność 180+ km; trasa do 800–1100 km`,`datalink 180+ km; route 800–1,100 km`),endurance:e(`8 h (VTOL) / 10 h (stałopłat)`,`8 h (VTOL) / 10 h (fixed-wing)`),ceiling:e(`4500–5000 m`,`4,500–5,000 m`),engine:e(`4-suw benzynowy`,`4-stroke petrol`),guidance:e(`radio 180+ km, INS/GNSS`,`180+ km radio, INS/GNSS`),launch:e(`pas / VTOL / katapulta`,`runway / VTOL / catapult`)}},{id:`tb2`,image:`/drones/tb2.jpg`,typeId:`isr-male`,domain:`air`,theaters:[`ukraine`,`africa`,`middle-east`,`global`],year:`2020–2026`,featured:!0,name:e(`Bayraktar TB2`,`Bayraktar TB2`),origin:e(`Turcja (Baykar)`,`Türkiye (Baykar)`),operators:e(`SZU (wczesna faza); 30+ państw`,`AFU (early phase); 30+ countries`),role:e(`MALE uzbrojony, ikona eksportu`,`Armed MALE, export icon`),note:e(`Ikona 2022 r.; na froncie ukraińskim wyparty z pierwszej linii przez zagęszczoną OPL. Nadal kluczowy w Afryce, na Kaukazie i w eksporcie (ponad 30 operatorów). Cztery pociski MAM-L/C pod skrzydłami. Czas lotu do 27 h.`,`The icon of 2022; on the Ukrainian front it was pushed off the first line by denser air defences. Still central in Africa, the Caucasus and export (30+ operators). Four MAM-L/C missiles under the wings. Endurance up to 27 h.`),specs:{length:e(`6,5 m`,`6.5 m`),span:e(`12,0 m`,`12.0 m`),mtow:e(`650–700 kg`,`650–700 kg`),payload:e(`150 kg (4× MAM-L/C + gimbal)`,`150 kg (4× MAM-L/C + gimbal)`),speed:e(`220 km/h`,`220 km/h`),cruise:e(`130 km/h`,`130 km/h`),range:e(`do 300 km LOS`,`up to 300 km LOS`),endurance:e(`27 h`,`27 h`),ceiling:e(`7620 m (25 000 ft)`,`7,620 m (25,000 ft)`),engine:e(`Rotax 912, 100 KM, śmigło pchające`,`Rotax 912, 100 hp, pusher`),guidance:e(`SATCOM / LOS, EO/IR, laser`,`SATCOM / LOS, EO/IR, laser`),launch:e(`pas startowy`,`runway`),cost:e(`ok. 5 mln USD za kompleks`,`about USD 5 million per complex`)}},{id:`ram2x`,image:`/drones/ram2x.jpg`,typeId:`loitering`,domain:`air`,theaters:[`ukraine`],year:`2025–2026`,name:e(`RAM-2X`,`RAM-2X`),origin:e(`Ukraina`,`Ukraine`),operators:e(`Siły Zbrojne Ukrainy`,`Armed Forces of Ukraine`),role:e(`Amunicja krążąca średniego zasięgu`,`Medium-range loitering munition`),note:e(`Ukraińska odpowiedź na Lanceta: skrzydło w układzie X, kamera w nosie, operator w pętli. Uderzenia w głąb taktycznego zaplecza — haubice, OPL, stanowiska dowodzenia. Zasięg w relacjach 30–150 km za linią, zależnie od wersji i przekaźnika.`,`Ukraine’s answer to the Lancet: an X-wing, a nose camera, operator in the loop. Strikes into the tactical rear — howitzers, air defences, command posts. Reported reach 30–150 km behind the line, depending on variant and relay.`),specs:{span:e(`układ X, ok. 1,5–2 m`,`X-layout, about 1.5–2 m`),mtow:e(`ok. 8–12 kg`,`about 8–12 kg`),warhead:e(`ok. 3–4 kg`,`about 3–4 kg`),speed:e(`ok. 100–140 km/h`,`about 100–140 km/h`),range:e(`30–150 km (zależnie od wersji)`,`30–150 km (by variant)`),endurance:e(`ok. 40–60 min`,`about 40–60 min`),engine:e(`elektryczny`,`electric`),guidance:e(`EO, operator w pętli`,`EO, operator in the loop`),launch:e(`katapulta / rampa`,`catapult / ramp`)}},{id:`warmate`,image:`/drones/warmate.jpg`,typeId:`loitering`,domain:`air`,theaters:[`ukraine`,`nato`],year:`2022–2026`,name:e(`WB Warmate`,`WB Warmate`),origin:e(`Polska (WB Group)`,`Poland (WB Group)`),operators:e(`SZU, Wojsko Polskie i inni`,`AFU, Polish Armed Forces and others`),role:e(`Przenośna amunicja krążąca`,`Man-portable loitering munition`),note:e(`Polska amunicja krążąca piechoty. Głowice HE-FRAG i HEAT. Jedna z nielicznych zachodnich konstrukcji tej klasy szeroko obecnych w Ukrainie. Warmate 2 i TL powiększają masę i zasięg.`,`A Polish infantry loitering munition. HE-FRAG and HEAT warheads. One of the few Western designs of this class widely present in Ukraine. Warmate 2 and TL increase mass and range.`),specs:{length:e(`1,10 m`,`1.10 m`),span:e(`1,60 m`,`1.60 m`),mtow:e(`5,3–5,7 kg`,`5.3–5.7 kg`),warhead:e(`1,4 kg (HE-FRAG / HEAT)`,`1.4 kg (HE-FRAG / HEAT)`),speed:e(`150 km/h`,`150 km/h`),cruise:e(`80 km/h`,`80 km/h`),range:e(`ok. 30 km`,`about 30 km`),endurance:e(`50–70 min`,`50–70 min`),ceiling:e(`500 m AGL (typ.)`,`500 m AGL (typ.)`),engine:e(`elektryczny`,`electric`),guidance:e(`EO, operator w pętli`,`EO, operator in the loop`),launch:e(`wyrzutnia pneumatyczna / z ręki`,`pneumatic tube / hand`)}},{id:`switchblade-300`,image:`/drones/switchblade.jpg`,typeId:`loitering`,domain:`air`,theaters:[`ukraine`,`nato`],year:`2022–2026`,name:e(`Switchblade 300`,`Switchblade 300`),origin:e(`USA (AeroVironment)`,`USA (AeroVironment)`),operators:e(`USA, SZU`,`USA, AFU`),role:e(`Plecakowa amunicja krążąca`,`Backpack loitering munition`),note:e(`Wyrzutnia rurowa, masa systemu ok. 2,5 kg. Głowica przeciwpiechotna. W Ukrainie używany od 2022 r.; ograniczona liczba i krótki czas lotu (ok. 15 min) sprawiły, że nie zastąpił masowego FPV. Wersja 400 wypełnia lukę między 300 a 600.`,`A tube launcher, system mass about 2.5 kg. Anti-personnel warhead. Used in Ukraine from 2022; limited numbers and a short 15-minute flight meant it never replaced mass FPV. The 400 fills the gap between 300 and 600.`),specs:{length:e(`0,49 m (w tubie ok. 0,61 m)`,`0.49 m (tube ~0.61 m)`),mtow:e(`ok. 2,5 kg (system)`,`about 2.5 kg (system)`),warhead:e(`ok. 0,3 kg, przeciwpiechotna`,`about 0.3 kg, anti-personnel`),speed:e(`101 km/h`,`101 km/h`),range:e(`10 km`,`10 km`),endurance:e(`15 min`,`15 min`),engine:e(`elektryczny, śmigło pchające`,`electric, pusher`),guidance:e(`EO, GPS, operator w pętli`,`EO, GPS, operator in the loop`),launch:e(`wyrzutnia rurowa`,`tube launcher`)}},{id:`switchblade-600`,image:`/drones/switchblade600.jpg`,typeId:`loitering`,domain:`air`,theaters:[`ukraine`,`nato`],year:`2023–2026`,name:e(`Switchblade 600`,`Switchblade 600`),origin:e(`USA (AeroVironment)`,`USA (AeroVironment)`),operators:e(`USA, SZU`,`USA, AFU`),role:e(`Amunicja krążąca przeciwpancerna`,`Anti-armour loitering munition`),note:e(`Głowica klasy Javelin. Program LASSO / Launched Effects. Zamówienie Armii USA na 2026 r.: 294 pociski. Koszt budżetowy ok. 170 tys. USD za sztukę — rząd wielkości powyżej Lanceta, stąd mniejsza masa użycia.`,`A Javelin-class warhead. LASSO / Launched Effects programme. US Army 2026 order: 294 rounds. Budget cost about USD 170 thousand each — an order of magnitude above the Lancet, hence far less massed use.`),specs:{length:e(`1,30 m`,`1.30 m`),mtow:e(`22,7 kg`,`22.7 kg`),warhead:e(`EFP klasy Javelin (ok. 3–5 kg)`,`Javelin-class EFP (~3–5 kg)`),speed:e(`185 km/h`,`185 km/h`),range:e(`40+ km (90+ z forward pass)`,`40+ km (90+ with forward pass)`),endurance:e(`40 min`,`40 min`),engine:e(`elektryczny`,`electric`),guidance:e(`EO/IR, GPS, operator w pętli`,`EO/IR, GPS, operator in the loop`),launch:e(`wyrzutnia rurowa / pojazd`,`tube / vehicle`),cost:e(`ok. 170 tys. USD (budżet US Army)`,`about USD 170 thousand (US Army budget)`)}},{id:`fp1`,image:`/drones/fp1.jpg`,typeId:`owa-deep`,domain:`air`,theaters:[`ukraine`],year:`2024–2026`,featured:!0,name:e(`Fire Point FP-1`,`Fire Point FP-1`),origin:e(`Ukraina (Fire Point)`,`Ukraine (Fire Point)`),operators:e(`SZU, GUR, SBU, SSO`,`AFU, HUR, SBU, SSO`),role:e(`Tani deep-strike na 1600–2700 km`,`Cheap deep strike to 1,600–2,700 km`),note:e(`Sklejka, pianka, włókno szklane, dwa wysięgniki, start z rampy przyspieszaczem stałopaliwowym. Głowica 60–120 kg. Zasięg bazowy 1600 km; wariant z integralnymi zbiornikami skrzydłowymi — 2700 km. 9 IX 2026 r. uderzenie w Nowy Urengoj, ok. 3200 km. Koszt ok. 55 tys. USD. Ponad 5000 sztuk od X 2024. Opcjonalnie dwa FPV pod skrzydłami.`,`Plywood, foam, glass fibre, twin booms, solid-rocket boost off a ramp. Warhead 60–120 kg. Baseline range 1,600 km; wing-integral tanks stretch it to 2,700 km. On 9 Sep 2026 a strike on Novy Urengoy, about 3,200 km. Cost about USD 55 thousand. More than 5,000 built since Oct 2024. Optional pair of FPV under the wings.`),specs:{span:e(`proste skrzydło, warianty wydłużane`,`straight wing, extended variants`),mtow:e(`ok. 330 kg`,`about 330 kg`),payload:e(`do 120 kg`,`up to 120 kg`),warhead:e(`60–120 kg (odłamkowa / kumulacyjna)`,`60–120 kg (FRAG / shaped charge)`),speed:e(`205 km/h`,`205 km/h`),cruise:e(`140–180 km/h`,`140–180 km/h`),range:e(`1600 km (baza); 2700 km (ER); rekord ~3200 km`,`1,600 km (base); 2,700 km (ER); record ~3,200 km`),endurance:e(`wiele godzin (zależnie od paliwa)`,`many hours (fuel-dependent)`),engine:e(`dwucylindrowy tłokowy + RATO`,`twin-cylinder piston + RATO`),guidance:e(`INS + GNSS z ECCM; Starlink w fazie terminalnej`,`INS + GNSS with ECCM; Starlink in terminal`),launch:e(`rampa + przyspieszacz stałopaliwowy`,`ramp + solid booster`),cost:e(`ok. 55 tys. USD`,`about USD 55 thousand`)}},{id:`fp2`,image:`/drones/fp1.jpg`,typeId:`owa-mid`,domain:`air`,theaters:[`ukraine`],year:`2025–2026`,name:e(`Fire Point FP-2`,`Fire Point FP-2`),origin:e(`Ukraina (Fire Point)`,`Ukraine (Fire Point)`),operators:e(`Siły Bezzałogowych Systemów UA`,`Unmanned Systems Forces of Ukraine`),role:e(`Uderzenie na zaplecze taktyczne`,`Strike into the tactical rear`),note:e(`Według ocen 2026 r. ok. 60% ukraińskich uderzeń dronowych tej klasy. Dwa tryby: ATR na cele stałe, sterowanie ręczne na ruchome. Producent: 105 kg na 370 km albo 200 kg na 700 km — liczby niepotwierdzone bojowo. W maju 2026 r. niekierowane rakiety S-5/S-8 z wyrzutni podskrzydłowych.`,`On 2026 estimates, about 60% of Ukrainian drone strikes in this class. Dual mode: ATR on fixed targets, manual control on movers. Maker’s claim: 105 kg to 370 km or 200 kg to 700 km — not combat-validated. In May 2026, unguided S-5/S-8 rockets from underwing rails.`),specs:{mtow:e(`klasa kilkuset kg`,`hundreds of kg class`),payload:e(`60–120 kg (deklaracje do 200 kg)`,`60–120 kg (claims up to 200 kg)`),warhead:e(`105 kg / 200 kg (dwie konfiguracje)`,`105 kg / 200 kg (two configs)`),range:e(`90–200 km; producent do 370–700 km`,`90–200 km; maker 370–700 km`),engine:e(`tłokowy`,`piston`),guidance:e(`INS/GNSS; ATR albo RC`,`INS/GNSS; ATR or RC`),launch:e(`rampa`,`ramp`),cost:e(`rząd 50 tys. EUR (wraz z FP-1)`,`order of EUR 50 thousand (with FP-1)`)}},{id:`liutyi`,image:`/drones/liutyi.jpg`,typeId:`owa-deep`,domain:`air`,theaters:[`ukraine`],year:`2022–2026`,featured:!0,name:e(`AN-196 Liutyj`,`AN-196 Liutyi`),aka:e(`Лютий — „Srogi”`,`Лютий — “Fierce”`),origin:e(`Ukraina (Ukroboronprom / Antonow)`,`Ukraine (Ukroboronprom / Antonov)`),operators:e(`GUR / SZU`,`HUR / AFU`),role:e(`Główny deep-strike na rafinerie RF`,`Principal deep strike on Russian refineries`),note:e(`Ukraiński odpowiednik Shaheda, ale bliższy małemu samolotowi: klasyczny układ, podwozie, śmigło pchające. Oficjalnie 1000 km i 50 kg; późniejsze serie ok. 75 kg i do 2000 km. Koszt powyżej 200 tys. USD. Niemcy zapowiedziały w 2026 r. inwestycję ponad 100 mln EUR w produkcję. INS+GNSS, bez powszechnie potwierdzonego seekera terminalnego.`,`Ukraine’s counterpart to the Shahed, but closer to a small aircraft: conventional layout, undercarriage, pusher prop. Officially 1,000 km and 50 kg; later series about 75 kg and up to 2,000 km. Cost above USD 200 thousand. Germany pledged in 2026 over EUR 100 million for production. INS+GNSS, no widely confirmed terminal seeker.`),specs:{length:e(`ok. 4,4 m`,`about 4.4 m`),span:e(`ok. 6,7 m`,`about 6.7 m`),mtow:e(`ok. 300 kg`,`about 300 kg`),warhead:e(`50 kg (wczesny) / ok. 75 kg (późny)`,`50 kg (early) / ~75 kg (later)`),speed:e(`ok. 160 km/h`,`about 160 km/h`),range:e(`1000–2000 km`,`1,000–2,000 km`),endurance:e(`wiele godzin`,`many hours`),engine:e(`tłokowy, śmigło pchające`,`piston, pusher propeller`),guidance:e(`INS + GNSS`,`INS + GNSS`),launch:e(`pas / krótki rozbieg`,`runway / short roll`),cost:e(`>200 tys. USD`,`> USD 200 thousand`)}},{id:`palianytsia`,image:`/drones/palianytsia.jpg`,typeId:`jet-drone`,domain:`air`,theaters:[`ukraine`],year:`2025–2026`,featured:!0,name:e(`UAV-290 Palianytsia`,`UAV-290 Palianytsia`),origin:e(`Ukraina (KB Łucz / Ukroboronprom)`,`Ukraine (Luch Design Bureau / Ukroboronprom)`),operators:e(`Siły Zbrojne Ukrainy`,`Armed Forces of Ukraine`),role:e(`Rakietodron na cele stałe`,`Missile-drone against fixed targets`),tidbit:e(`Nazwa od ukraińskiego chleba. Kto nie potrafi powiedzieć „palianytsia”, jest „obcy”. Konstruktorzy z KB Łucz nie wybrali jej przypadkiem.`,`Named after a Ukrainian loaf. Whoever cannot say “palianytsia” is “the other”. Luch Design Bureau did not pick it by accident.`),note:e(`Oficjalne oznaczenie UAV-290, potwierdzone na MSPO 2026 w Kielcach. Silnik turboodrzutowy, start z naczepy przyspieszaczem stałopaliwowym. Prędkość przelotowa do 800 km/h, głowica 100 kg, zasięg 650 km. Nawigacja INS odporna na WRE, korygowana GPS. Granica między dronem a pociskiem manewrującym jest tu umowna.`,`Official designation UAV-290, confirmed at MSPO 2026 in Kielce. Turbojet, trailer launch with a solid booster. Cruise up to 800 km/h, 100 kg warhead, 650 km range. EW-hardened INS, GPS-corrected. The line between drone and cruise missile is conventional here.`),specs:{length:e(`3,5 m`,`3.5 m`),span:e(`1,7 m`,`1.7 m`),mtow:e(`350 kg`,`350 kg`),warhead:e(`100 kg`,`100 kg`),speed:e(`do 800 km/h`,`up to 800 km/h`),cruise:e(`do 800 km/h`,`up to 800 km/h`),range:e(`650 km`,`650 km`),engine:e(`turboodrzutowy + RATO`,`turbojet + RATO`),guidance:e(`INS + GPS`,`INS + GPS`),launch:e(`naczepa, przyspieszacz stałopaliwowy`,`semi-trailer, solid booster`)}},{id:`peklo`,image:`/drones/geran3.jpg`,typeId:`jet-drone`,domain:`air`,theaters:[`ukraine`],year:`2025–2026`,name:e(`Pekło`,`Peklo`),aka:e(`Пекло — „Piekło”`,`Пекло — “Hell”`),origin:e(`Ukraina (Ukroboronprom)`,`Ukraine (Ukroboronprom)`),operators:e(`GUR / SZU`,`HUR / AFU`),role:e(`Szybki rakietodron`,`Fast missile-drone`),note:e(`Kilka razy szybszy od Liutego. Zasięg do 700 km, głowica 23–50 kg zależnie od źródła, prędkość 700–1000 km/h. Nawigacja odporna na WRE w fazie terminalnej. Mniej masowy niż FP-1, za to trudniejszy do zestrzelenia przez OPL nastawioną na Gerany.`,`Several times faster than Liutyi. Range up to 700 km, warhead 23–50 kg depending on the source, speed 700–1,000 km/h. EW-hardened navigation in the terminal phase. Less massed than the FP-1, but harder for air defences tuned to Gerans to kill.`),specs:{range:e(`do 700 km`,`up to 700 km`),warhead:e(`23–50 kg`,`23–50 kg`),speed:e(`700–1000 km/h`,`700–1,000 km/h`),payload:e(`od 23 kg`,`from 23 kg`),engine:e(`odrzut / rakietodron`,`jet / missile-drone`),guidance:e(`INS/GNSS, odporność WRE w terminalu`,`INS/GNSS, EW-hardened terminal`)}},{id:`flamingo`,image:`/drones/palianytsia.jpg`,typeId:`owa-deep`,domain:`air`,theaters:[`ukraine`],year:`2025–2026`,name:e(`FP-5 Flamingo`,`FP-5 Flamingo`),origin:e(`Ukraina (Fire Point)`,`Ukraine (Fire Point)`),operators:e(`Marynarka / SZU`,`Navy / AFU`),role:e(`Pocisk manewrujący klasy 6 t`,`6-tonne-class cruise missile`),note:e(`Na granicy drona i pocisku manewrującego. Silnik AI-25TL, masa ok. 6 t, głowica 1150 kg — 2,5 raza cięższa niż w Tomahawku Block V. Zasięg do 3000 km, prędkość 850–950 km/h. Debiut bojowy wrzesień 2025, produkcja 2026. Nie jest tanim OWA: to pełnowymiarowy pocisk.`,`On the line between drone and cruise missile. AI-25TL engine, mass about 6 t, warhead 1,150 kg — 2.5× a Tomahawk Block V. Range up to 3,000 km, speed 850–950 km/h. Combat debut September 2025, production 2026. Not a cheap OWA: a full-size missile.`),specs:{mtow:e(`ok. 6 t`,`about 6 t`),warhead:e(`1150 kg`,`1,150 kg`),speed:e(`850–950 km/h`,`850–950 km/h`),range:e(`do 3000 km`,`up to 3,000 km`),engine:e(`AI-25TL (turbowentylatorowy)`,`AI-25TL (turbofan)`),guidance:e(`INS/GNSS (szczegóły niejawne)`,`INS/GNSS (details classified)`),launch:e(`wyrzutnia naziemna`,`ground launcher`)}},{id:`magura-v5`,image:`/drones/magura-sea.jpg`,typeId:`usv`,domain:`sea`,theaters:[`ukraine`],year:`2023–2026`,featured:!0,name:e(`MAGURA V5`,`MAGURA V5`),origin:e(`Ukraina (UForce / GUR)`,`Ukraine (UForce / HUR)`),operators:e(`Główny Zarząd Wywiadu Ukrainy`,`Defence Intelligence of Ukraine`),role:e(`USV uderzeniowy i rakietowy`,`Strike and missile USV`),note:e(`Pierwszy bezzałogowiec nawodny, który zatopił okręt wojenny; zestrzelił też śmigłowce pociskami R-73. Długość 5,5 m, zasięg 800 km, ładunek 300–350 kg. W 2026 r. wariant z interceptorami Shahedów startującymi z pokładu.`,`The first uncrewed surface vessel to sink a warship; it also downed helicopters with R-73 missiles. Length 5.5 m, range 800 km, payload 300–350 kg. In 2026 a variant launching Shahed interceptors from the deck.`),specs:{length:e(`5,5 m`,`5.5 m`),span:e(`szerokość ok. 1,5 m`,`beam about 1.5 m`),mtow:e(`ok. 1000 kg`,`about 1,000 kg`),payload:e(`300–350 kg; 2× R-73`,`300–350 kg; 2× R-73`),warhead:e(`do 320 kg (wariant uderzeniowy)`,`up to 320 kg (strike variant)`),speed:e(`do 78 km/h (ok. 42 w)`,`up to 78 km/h (~42 kn)`),range:e(`800 km`,`800 km`),endurance:e(`wiele godzin`,`many hours`),engine:e(`benzynowy / dieslowski`,`petrol / diesel`),guidance:e(`satelita + operator w pętli`,`satellite + operator in the loop`),cost:e(`ok. 250–280 tys. USD`,`about USD 250–280 thousand`)}},{id:`magura-v7`,image:`/drones/magura.jpg`,typeId:`usv`,domain:`sea`,theaters:[`ukraine`,`nato`],year:`2025–2026`,name:e(`MAGURA V7`,`MAGURA V7`),origin:e(`Ukraina (UForce); licencja USA ReconCraft VII`,`Ukraine (UForce); US licence ReconCraft VII`),operators:e(`GUR`,`HUR`),role:e(`Cięższy USV rakietowy`,`Heavier missile USV`),note:e(`7,2 m, diesel 270 KM, ładunek 650 kg, dwa AIM-9 albo pocisk manewrujący. Autonomia 48 h–7 dni z agregatem. MAGURA V11: oceaniczny, do 18 interceptorów Sting. W 2026 r. licencja amerykańska ReconCraft VII.`,`7.2 m, 270 hp diesel, 650 kg payload, two AIM-9s or a cruise missile. Endurance 48 h–7 days with a generator. MAGURA V11: oceanic, up to 18 Sting interceptors. In 2026 a US licence as ReconCraft VII.`),specs:{length:e(`7,2 m`,`7.2 m`),payload:e(`650 kg; 2× AIM-9 lub KM`,`650 kg; 2× AIM-9 or a CM`),speed:e(`ok. 72 km/h`,`about 72 km/h`),range:e(`do 1000 km`,`up to 1,000 km`),endurance:e(`48 h – 7 dni`,`48 h – 7 days`),engine:e(`diesel 270 KM`,`270 hp diesel`),guidance:e(`satelita, autonomia wielodniowa`,`satellite, multi-day autonomy`)}},{id:`sea-baby`,image:`/drones/seababy.jpg`,typeId:`usv`,domain:`sea`,theaters:[`ukraine`],year:`2023–2026`,name:e(`Sea Baby`,`Sea Baby`),origin:e(`Ukraina (SBU)`,`Ukraine (SBU)`),operators:e(`SBU / 385. batalion USV`,`SBU / 385th USV battalion`),role:e(`Ciężki USV SBU`,`Heavy SBU USV`),note:e(`Ataki na Most Krymski, okręty, Kinburn. Ładunek do 850 kg, zasięg ≥1000 km, prędkość do 90 km/h. Warianty z RPV-16 i Gradem. 2026: Sub Sea Baby — pierwszy bojowy atak podwodny na okręt projektu 636 (Warszawianka).`,`Attacks on the Kerch Bridge, warships, Kinburn. Payload up to 850 kg, range ≥1,000 km, speed up to 90 km/h. Variants with RPV-16 and Grad. 2026: Sub Sea Baby — the first combat underwater attack on a Project 636 (Kilo) submarine.`),specs:{length:e(`ok. 5,5–6 m`,`about 5.5–6 m`),payload:e(`do 850 kg`,`up to 850 kg`),warhead:e(`warianty z RPV-16 i Gradem`,`variants with RPV-16 and Grad`),speed:e(`do 90 km/h`,`up to 90 km/h`),range:e(`≥1000 km`,`≥1,000 km`),engine:e(`spalinowy`,`ICE`),guidance:e(`satelita + operator`,`satellite + operator`)}},{id:`sting`,image:`/drones/fpv.jpg`,typeId:`interceptor`,domain:`air`,theaters:[`ukraine`],year:`2025–2026`,name:e(`Sting (Wild Hornets)`,`Sting (Wild Hornets)`),aka:e(`Dzikie szerszenie`,`Wild Hornets`),origin:e(`Ukraina (Wild Hornets)`,`Ukraine (Wild Hornets)`),operators:e(`SZU, SBU Alfa, OPL dronowa`,`AFU, SBU Alpha, drone air defence`),role:e(`Najskuteczniejszy interceptor Shahedów`,`The most effective Shahed interceptor`),tidbit:e(`W sierpniu 2026 r. zestrzelił zwiadowcę na 7472 m — ówczesny rekord świata w starciu dron–dron. Poseł Zablotskyj sterował jednym egzemplarzem z odległości 2000 km.`,`In August 2026 it downed a scout at 7,472 m — then a world record for drone-on-drone combat. MP Zablotskyy flew one from 2,000 km away.`),note:e(`Interceptor firmy Wild Hornets, drukowany w 3D. Do czerwca 2026 r. zestrzelił około 9 tys. Shahedów i Gerber — przez siedem miesięcy z rzędu był najskuteczniejszym ukraińskim myśliwcem dronowym. Prędkość do 280 km/h, pułap 7 km (wyższy niż u P1-SUN, wolniejszy o 70–100 km/h). W kwietniu 2026 r. po raz pierwszy wystartował z kutra Magura — pływająca bateria osiemnastu Stingów. Produkcja: ponad 10 tys. sztuk miesięcznie (marzec 2026). Koszt: około 2000 dolarów.`,`A 3D-printed interceptor from Wild Hornets. By June 2026 it had downed about 9,000 Shaheds and Gerberas — Ukraine’s top anti-Shahed hunter for seven months running. Speed up to 280 km/h, ceiling 7 km (higher than the P1-SUN, 70–100 km/h slower). In April 2026 it first launched from a Magura boat — a floating battery of eighteen Stings. Output: over 10,000 a month (March 2026). Cost: about USD 2,000.`),specs:{mtow:e(`kilka kilogramów`,`several kilograms`),warhead:e(`ok. 400 g`,`about 400 g`),speed:e(`do 280 km/h`,`up to 280 km/h`),ceiling:e(`do 7 km (rekord 7472 m)`,`up to 7 km (record 7,472 m)`),range:e(`strefa OPL; sterowanie przez Starlink`,`AD zone; Starlink control`),endurance:e(`kilkanaście minut`,`a dozen minutes`),engine:e(`4× silnik elektryczny, kadłub z druku 3D`,`4× electric motors, 3D-printed airframe`),guidance:e(`FPV / namierzanie, opcjonalnie Starlink`,`FPV / tracking, optional Starlink`),cost:e(`ok. 2000 USD`,`about USD 2,000`)}},{id:`ratel`,image:`/drones/ratel.jpg`,typeId:`ugv`,domain:`ground`,theaters:[`ukraine`],year:`2024–2026`,name:e(`Ratel S / X`,`Ratel S / X`),origin:e(`Ukraina (Ratel Robotics)`,`Ukraine (Ratel Robotics)`),operators:e(`Siły Zbrojne Ukrainy`,`Armed Forces of Ukraine`),role:e(`UGV minujący i kamikaze`,`Mining and kamikaze UGV`),note:e(`Czterokołowy robot do minowania (TM-62) i uderzeń samobójczych. Sierpień 2026: ponad 1100 misji w miesiącu w skali rodziny Ratel. Wersja amfibia w rozwoju. Jeden z nielicznych UGV z udokumentowanym masowym użyciem, nie tylko prototypem.`,`A four-wheel robot for mining (TM-62) and suicide runs. August 2026: more than 1,100 missions in a month across the Ratel family. An amphibious version in development. One of the few UGVs with documented mass use, not just a prototype.`),specs:{length:e(`ok. 0,8–1,2 m`,`about 0.8–1.2 m`),mtow:e(`ok. 15–30 kg`,`about 15–30 kg`),payload:e(`mina TM-62 / ładunek`,`TM-62 mine / charge`),range:e(`kilka km`,`a few km`),engine:e(`elektryczny, 4 koła`,`electric, 4 wheels`),guidance:e(`radio / światłowód`,`radio / fibre`)}},{id:`shahed136`,image:`/drones/shahed.jpg`,typeId:`owa-deep`,domain:`air`,theaters:[`ukraine`,`middle-east`,`global`],year:`2021–2026`,featured:!0,name:e(`Shahed-136 / Geran-2`,`Shahed-136 / Geran-2`),aka:e(`„skuter”, Geranium-2`,`“moped”, Geranium-2`),origin:e(`Iran (HESA); produkcja RF w Ałabudze`,`Iran (HESA); RU production at Alabuga`),operators:e(`Iran, RF, Huti, Hezbollah, milicje Iraku`,`Iran, Russia, Houthis, Hezbollah, Iraqi militias`),role:e(`Masowy OWA saturacyjny`,`Mass saturating OWA`),note:e(`Delta z popychaczem, silnik MD-550 (ok. 50 KM) — charakterystyczny warczący „skuter”. Głowica irańska ok. 50 kg; rosyjska bywa dociążana do 90 kg kosztem paliwa (zasięg spada do ok. 650 km). Zasięg nominalny 1000–2500 km. Do marca 2026 r. ok. 57 tys. startów rodziny. Ałabuga: ok. 2800 Geran-2 miesięcznie (VIII 2026). Kopiowany: LUCAS (USA), Papa Delta (Tajwan).`,`A pusher delta, MD-550 engine (~50 hp) — the buzzing “moped”. Iranian warhead about 50 kg; the Russian one can be ballasted to 90 kg at the cost of fuel (range falls to ~650 km). Nominal range 1,000–2,500 km. By March 2026 about 57,000 family launches. Alabuga: ~2,800 Geran-2 a month (Aug 2026). Copied: LUCAS (USA), Papa Delta (Taiwan).`),specs:{length:e(`3,5 m`,`3.5 m`),span:e(`2,5 m`,`2.5 m`),mtow:e(`200 kg`,`200 kg`),warhead:e(`50 kg (IR); 50–90 kg (RF)`,`50 kg (IR); 50–90 kg (RU)`),speed:e(`185 km/h`,`185 km/h`),cruise:e(`ok. 150–180 km/h`,`about 150–180 km/h`),range:e(`1000–2500 km (90 kg: ~650 km)`,`1,000–2,500 km (90 kg: ~650 km)`),endurance:e(`ok. 11–12 h`,`about 11–12 h`),ceiling:e(`do 4000 m`,`up to 4,000 m`),engine:e(`Mado MD-550, 4-cyl. dwusuw, ~50 KM`,`Mado MD-550, 4-cyl two-stroke, ~50 hp`),guidance:e(`GNSS + INS; CRPA; od I 2026 Starlink (RF)`,`GNSS + INS; CRPA; Starlink from Jan 2026 (RU)`),launch:e(`rampa samochodowa + RATO`,`vehicle ramp + RATO`),cost:e(`30–50 tys. USD (wytworzenie); sprzedaż IR→RF ~193 tys.`,`USD 30–50 thousand (build); IR→RU sale ~193 thousand`)}},{id:`geran3`,image:`/drones/geran3.jpg`,typeId:`jet-drone`,domain:`air`,theaters:[`ukraine`,`middle-east`],year:`2025–2026`,name:e(`Geran-3 / Shahed-238`,`Geran-3 / Shahed-238`),origin:e(`Iran / Rosja (silniki m.in. z Chin wg GUR)`,`Iran / Russia (engines from China per HUR)`),operators:e(`SZ RF, Iran`,`Russian forces, Iran`),role:e(`Odrzutowy OWA`,`Jet OWA`),note:e(`Przełom 2026 r.: odrzutowce codziennie w salwach sierpnia. 350 (VI) → 1600 (VII) → 2800 (VIII). Shahed-238: turboodrzut TJ150, prędkość przelotowa ok. 520 km/h, masa ok. 380 kg. Geran-5: ok. 500 km/h, pułap 5000 m. Warianty z R-60 i Wierbą przeciw śmigłowcom OPL.`,`The 2026 break: jets in daily August salvos. 350 (Jun) → 1,600 (Jul) → 2,800 (Aug). Shahed-238: TJ150 turbojet, cruise about 520 km/h, mass about 380 kg. Geran-5: about 500 km/h, ceiling 5,000 m. Variants with R-60 and Verba against AD helicopters.`),specs:{length:e(`3,5 m`,`3.5 m`),span:e(`ok. 3 m`,`about 3 m`),mtow:e(`ok. 380 kg (Shahed-238)`,`about 380 kg (Shahed-238)`),warhead:e(`50–90 kg (w tym termobaryczna)`,`50–90 kg (incl. thermobaric)`),speed:e(`450–600+ km/h`,`450–600+ km/h`),cruise:e(`ok. 520 km/h (238)`,`about 520 km/h (238)`),range:e(`620–2000 km (zależnie od wersji)`,`620–2,000 km (by version)`),ceiling:e(`do 5000 m (Geran-5)`,`up to 5,000 m (Geran-5)`),engine:e(`turboodrzut TJ150 / chińskie kopie`,`TJ150 turbojet / Chinese copies`),guidance:e(`INS/GNSS; warianty IR/optyka/radar`,`INS/GNSS; IR/optical/radar variants`),launch:e(`rampa + RATO`,`ramp + RATO`)}},{id:`gerbera`,image:`/drones/gerbera.jpg`,typeId:`decoy`,domain:`air`,theaters:[`ukraine`],year:`2024–2026`,name:e(`Gerbera`,`Gerbera`),aka:e(`Parodija`,`Parodiya`),origin:e(`Rosja`,`Russia`),operators:e(`Siły Zbrojne RF`,`Russian Armed Forces`),role:e(`Wabik saturujący OPL`,`Decoy saturating air defences`),note:e(`Tanie skrzydło z pianki i sklejki, sylwetką naśladujące Gerana. Część lata jako czysty wabik, część niesie małą głowicę. W pakiecie z Geranami i pociskami manewrującymi zmusza OPL do zużywania rakiet po kilkaset tysięcy dolarów. Plan VIII 2026: 11 tys. sztuk rodziny Geran/Gerbera/Garpija.`,`A cheap foam-and-plywood wing, Geran-shaped. Some fly as pure decoys, some carry a small warhead. In packages with Gerans and cruise missiles it forces air defences to spend missiles worth hundreds of thousands of dollars. Aug 2026 plan: 11,000 of the Geran/Gerbera/Garpia family.`),specs:{length:e(`ok. 2,0 m`,`about 2.0 m`),span:e(`ok. 2,5 m`,`about 2.5 m`),mtow:e(`ok. 10–20 kg`,`about 10–20 kg`),warhead:e(`brak albo mała (wariant kamikaze)`,`none, or small (kamikaze variant)`),speed:e(`ok. 160 km/h`,`about 160 km/h`),range:e(`do 600 km`,`up to 600 km`),ceiling:e(`ok. 3000 m`,`about 3,000 m`),engine:e(`mały silnik tłokowy, pianka/sklejka`,`small piston, foam/plywood`),guidance:e(`GNSS (proste)`,`GNSS (simple)`),cost:e(`kilka tysięcy USD`,`a few thousand USD`)}},{id:`lancet`,image:`/drones/lancet2.jpg`,typeId:`loitering`,domain:`air`,theaters:[`ukraine`,`global`],year:`2022–2026`,featured:!0,name:e(`ZALA Lancet-3`,`ZALA Lancet-3`),origin:e(`Rosja (ZALA / Kalasznikow)`,`Russia (ZALA / Kalashnikov)`),operators:e(`Siły Zbrojne RF; eksport od II 2026`,`Russian forces; export from Feb 2026`),role:e(`Najskuteczniejsza amunicja krążąca wojny`,`The war’s most effective loitering munition`),note:e(`Układ X, kamera w nosie, operator w pętli. Głowice kumulacyjna, odłamkowa i termobaryczna. Nurkowanie ponad 300 km/h. ZALA/Orlan wskazują cel, Lancet dobija. Eksport od lutego 2026. Wyrzutnia jednoosobowa — produkcja seryjna od I 2026. Koszt 20–35 tys. USD — dużo taniej niż Switchblade 600.`,`X-layout, nose camera, operator in the loop. HEAT, fragmentation and thermobaric warheads. Dive above 300 km/h. ZALA/Orlan cue, Lancet kills. Export from February 2026. A one-person launcher — series production from Jan 2026. Cost USD 20–35 thousand — far cheaper than Switchblade 600.`),specs:{length:e(`1,65 m`,`1.65 m`),span:e(`ok. 1,2 m (układ X)`,`about 1.2 m (X-layout)`),mtow:e(`12 kg`,`12 kg`),warhead:e(`3–5 kg (HEAT / HE / TB)`,`3–5 kg (HEAT / HE / TB)`),speed:e(`nurkowanie >300 km/h`,`dive >300 km/h`),cruise:e(`80–110 km/h`,`80–110 km/h`),range:e(`40–70 km`,`40–70 km`),endurance:e(`40–60 min`,`40–60 min`),ceiling:e(`do 5000 m`,`up to 5,000 m`),engine:e(`elektryczny`,`electric`),guidance:e(`EO, operator w pętli; wskazanie z Orlana/ZALA`,`EO, operator in the loop; cue from Orlan/ZALA`),launch:e(`katapulta / rampa / wyrzutnia 1-os.`,`catapult / ramp / 1-person launcher`),cost:e(`20–35 tys. USD`,`USD 20–35 thousand`)}},{id:`kub`,image:`/drones/lancet.jpg`,typeId:`loitering`,domain:`air`,theaters:[`ukraine`],year:`2022–2026`,name:e(`Kub-BLA`,`Kub-BLA`),origin:e(`Rosja (ZALA / Kalasznikow)`,`Russia (ZALA / Kalashnikov)`),operators:e(`Siły Zbrojne RF`,`Russian Armed Forces`),role:e(`Tańsza amunicja krążąca`,`Cheaper loitering munition`),note:e(`Delta, prostsza i tańsza od Lanceta. Głowica ok. 3 kg, zasięg taktyczny ok. 15 km. Używana równolegle z Lancetem tam, gdzie nie potrzeba precyzji seekera EO wyższej klasy.`,`A delta, simpler and cheaper than the Lancet. Warhead about 3 kg, tactical range about 15 km. Used alongside the Lancet where a higher-grade EO seeker is not required.`),specs:{length:e(`0,95 m`,`0.95 m`),span:e(`1,20 m`,`1.20 m`),mtow:e(`ok. 9–12 kg`,`about 9–12 kg`),warhead:e(`ok. 3 kg`,`about 3 kg`),speed:e(`130 km/h`,`130 km/h`),range:e(`ok. 15 km`,`about 15 km`),endurance:e(`ok. 30 min`,`about 30 min`),ceiling:e(`1500 m`,`1,500 m`),engine:e(`elektryczny`,`electric`),guidance:e(`GNSS / proste EO`,`GNSS / simple EO`)}},{id:`orlan10`,image:`/drones/orlan.jpg`,typeId:`isr-tactical`,domain:`air`,theaters:[`ukraine`,`africa`,`global`],year:`2010–2026`,featured:!0,name:e(`Orlan-10 / Orlan-30`,`Orlan-10 / Orlan-30`),origin:e(`Rosja (STC)`,`Russia (STC)`),operators:e(`Siły Zbrojne RF`,`Russian Armed Forces`),role:e(`Kręgosłup rozpoznania RF`,`The backbone of Russian reconnaissance`),note:e(`Najważniejszy zwiadowca rosyjski wojny. Pętla: Orlan/ZALA/SuperCam → artyleria / Iskander / Lancet. Czas lotu do 16 h, łączność ok. 120 km. Start z katapulty, odzysk na spadochronie. Orlan-30 ma dalmierz laserowy do podświetlania celów.`,`The war’s most important Russian scout. The loop: Orlan/ZALA/SuperCam → artillery / Iskander / Lancet. Endurance up to 16 h, datalink about 120 km. Catapult launch, parachute recovery. Orlan-30 has a laser rangefinder for target designation.`),specs:{length:e(`1,80 m (Orlan-10)`,`1.80 m (Orlan-10)`),span:e(`3,10 m`,`3.10 m`),mtow:e(`15–18 kg (10) / ok. 30 kg (30)`,`15–18 kg (10) / about 30 kg (30)`),payload:e(`do 5,5 kg ISR; Orlan-30: laser`,`up to 5.5 kg ISR; Orlan-30: laser`),speed:e(`150 km/h (10) / 170 km/h (30)`,`150 km/h (10) / 170 km/h (30)`),cruise:e(`90–110 km/h`,`90–110 km/h`),range:e(`łączność ~120 km; trasa do 600 km`,`datalink ~120 km; route up to 600 km`),endurance:e(`do 16 h`,`up to 16 h`),ceiling:e(`5000–6000 m`,`5,000–6,000 m`),engine:e(`dwusuw benzynowy ok. 3,5 KM`,`two-stroke petrol ~3.5 hp`),guidance:e(`INS/GNSS + radio`,`INS/GNSS + radio`),launch:e(`katapulta; spadochron`,`catapult; parachute`)}},{id:`molniya2`,image:`/drones/molniya.jpg`,typeId:`fpv-wing`,domain:`air`,theaters:[`ukraine`],year:`2024–2026`,name:e(`Mołnija-2`,`Molniya-2`),origin:e(`Rosja`,`Russia`),operators:e(`Siły Zbrojne RF`,`Russian Armed Forces`),role:e(`Tani stałopłat kamikaze`,`Cheap fixed-wing kamikaze`),note:e(`Pianka i sklejka, śmigło pchające, start z rampy. Masowy mid-strike na logistykę ukraińską. Wariant przechwytujący „Baba Jagę” — do 220 km/h. Koszt rzędu 500–2000 USD. W 2026 r. jeden z najczęściej zestrzeliwanych — i najczęściej wystrzeliwanych — tanich stałopłatów.`,`Foam and plywood, pusher prop, ramp launch. Massed mid-strike on Ukrainian logistics. An interceptor variant against “Baba Yaga” — up to 220 km/h. Cost around USD 500–2,000. In 2026 one of the most often shot down — and most often launched — cheap monoplanes.`),specs:{length:e(`1,50 m`,`1.50 m`),span:e(`1,20 m`,`1.20 m`),mtow:e(`ok. 5–10 kg`,`about 5–10 kg`),warhead:e(`3–5 kg`,`3–5 kg`),speed:e(`190 km/h (interceptor do 220)`,`190 km/h (interceptor up to 220)`),range:e(`ok. 25–40 km`,`about 25–40 km`),ceiling:e(`ok. 3000 m`,`about 3,000 m`),engine:e(`elektryczny albo mały tłokowy`,`electric or small piston`),guidance:e(`FPV / GNSS`,`FPV / GNSS`),launch:e(`rampa`,`ramp`),cost:e(`500–2000 USD`,`USD 500–2,000`)}},{id:`orion`,image:`/drones/orion.jpg`,typeId:`isr-male`,domain:`air`,theaters:[`ukraine`],year:`2020–2026`,name:e(`Orion (Inochodziec)`,`Orion (Inokhodets)`),origin:e(`Rosja (Kronstadt)`,`Russia (Kronstadt)`),operators:e(`Siły Zbrojne RF`,`Russian Armed Forces`),role:e(`Rosyjski MALE uzbrojony`,`Russian armed MALE`),note:e(`Jedyny seryjny rosyjski UCAV klasy MALE. Ograniczona liczba, wysokie ryzyko nad ukraińską OPL — używany ostrożnie, z tyłu. Uzbrojenie powietrze–ziemia, czas lotu do 24 h. Nie odegrał roli porównywalnej z TB2 w 2022 r.`,`Russia’s only series MALE UCAV. Limited numbers, high risk over Ukrainian air defences — used cautiously, well back. Air-to-ground weapons, endurance up to 24 h. It never played a role comparable to the TB2 in 2022.`),specs:{length:e(`8,0 m`,`8.0 m`),span:e(`16,3 m`,`16.3 m`),mtow:e(`1000–1150 kg`,`1,000–1,150 kg`),payload:e(`200–250 kg`,`200–250 kg`),speed:e(`200 km/h`,`200 km/h`),range:e(`ok. 250 km`,`about 250 km`),endurance:e(`24 h`,`24 h`),ceiling:e(`7500 m`,`7,500 m`),engine:e(`Rotax 914 / analog, śmigło pchające`,`Rotax 914 / analogue, pusher`),guidance:e(`LOS / SATCOM, EO/IR`,`LOS / SATCOM, EO/IR`),launch:e(`pas startowy`,`runway`)}},{id:`mq9`,image:`/drones/mq9.jpg`,typeId:`isr-male`,domain:`air`,theaters:[`nato`,`middle-east`,`africa`,`global`],year:`2007–2026`,featured:!0,name:e(`MQ-9 Reaper`,`MQ-9 Reaper`),origin:e(`USA (General Atomics)`,`USA (General Atomics)`),operators:e(`USA, UK, Francja, Włochy, Holandia i inni`,`USA, UK, France, Italy, Netherlands and others`),role:e(`MALE Zachodu nr 1`,`The West’s number-one MALE`),note:e(`Nadal podstawowy uzbrojony bezzałogowiec NATO (ponad 500 sztuk), ale zestrzeliwany przez Huti — 17–19 maszyn od 2023 r. Hellfire, GBU, 27+ h w powietrzu. USA szuka tańszych następców; Reaper pozostaje jednak wzorcem, do którego porównuje się TB2, Akıncı i Wing Loong.`,`Still NATO’s baseline armed UAV (500+ airframes), but shot down by the Houthis — 17–19 aircraft since 2023. Hellfire, GBU, 27+ hours on station. The US is hunting cheaper successors; the Reaper remains the yardstick for TB2, Akıncı and Wing Loong.`),specs:{length:e(`11,0 m`,`11.0 m`),span:e(`20,1 m`,`20.1 m`),mtow:e(`4760 kg`,`4,760 kg`),payload:e(`1746 kg (3850 lb) — Hellfire, GBU, ISR`,`1,746 kg (3,850 lb) — Hellfire, GBU, ISR`),speed:e(`482 km/h`,`482 km/h`),cruise:e(`ok. 370 km/h`,`about 370 km/h`),range:e(`1850 km`,`1,850 km`),endurance:e(`27 h`,`27 h`),ceiling:e(`15 240 m (50 000 ft)`,`15,240 m (50,000 ft)`),engine:e(`Honeywell TPE331-10, turbośmigłowy`,`Honeywell TPE331-10 turboprop`),guidance:e(`SATCOM, EO/IR, radar`,`SATCOM, EO/IR, radar`),launch:e(`pas startowy`,`runway`),cost:e(`ok. 32 mln USD za sztukę`,`about USD 32 million each`)}},{id:`akinci`,image:`/drones/akinci.jpg`,typeId:`isr-male`,domain:`air`,theaters:[`global`,`africa`,`middle-east`],year:`2021–2026`,name:e(`Bayraktar Akıncı`,`Bayraktar Akıncı`),origin:e(`Turcja (Baykar)`,`Türkiye (Baykar)`),operators:e(`Turcja, Mali, Burkina Faso, Sudan (SAF) i inni`,`Türkiye, Mali, Burkina Faso, Sudan (SAF) and others`),role:e(`Ciężki UCAV eksportowy`,`Heavy export UCAV`),note:e(`Ponad 110 sztuk na początku 2026 r. Dwa turbośmigła (AI-450T albo PT6A), 8 węzłów, radar AESA, ładunek 1500 kg. W Sudanie — uderzenia SAF (ONZ: m.in. Yiha III i Akıncı). Klasa wyżej od TB2, taniej od Reapera.`,`More than 110 airframes at the start of 2026. Twin turboprops (AI-450T or PT6A), 8 hardpoints, AESA radar, 1,500 kg payload. In Sudan — SAF strikes (UN: Yiha III and Akıncı among others). A class above the TB2, cheaper than the Reaper.`),specs:{length:e(`12,5 m`,`12.5 m`),span:e(`20,0 m`,`20.0 m`),mtow:e(`5500–6000 kg`,`5,500–6,000 kg`),payload:e(`1500 kg, 8 węzłów`,`1,500 kg, 8 hardpoints`),speed:e(`361 km/h`,`361 km/h`),range:e(`7500 km (przelot)`,`7,500 km (ferry)`),endurance:e(`24 h`,`24 h`),ceiling:e(`12 192 m (40 000 ft)`,`12,192 m (40,000 ft)`),engine:e(`2× AI-450T albo PT6A, ~450 KM każdy`,`2× AI-450T or PT6A, ~450 hp each`),guidance:e(`SATCOM, AESA, EO/IR`,`SATCOM, AESA, EO/IR`),launch:e(`pas startowy`,`runway`)}},{id:`wingloong2`,image:`/drones/wingloong.jpg`,typeId:`isr-male`,domain:`air`,theaters:[`east-asia`,`middle-east`,`africa`,`global`],year:`2017–2026`,name:e(`Wing Loong II (GJ-2)`,`Wing Loong II (GJ-2)`),origin:e(`Chiny (AVIC/CAIG)`,`China (AVIC/CAIG)`),operators:e(`Chiny, ZEA, Arabia, Libia (LNA), Nigeria i inni`,`China, UAE, Saudi Arabia, Libya (LNA), Nigeria and others`),role:e(`Chiński MALE eksportowy`,`Chinese export MALE`),note:e(`Najskuteczniejszy chiński eksport lotniczy. Sześć węzłów, 480 kg, 32 h. W 2026 r. Iran zestrzelił WL-2 koło Szirazu. Arabia: linia WL-3 w Dżuddzie (ok. 48/rok, kontrakt rzędu 5 mld USD).`,`China’s most successful aviation export. Six hardpoints, 480 kg, 32 h. In 2026 Iran shot down a WL-2 near Shiraz. Saudi Arabia: a WL-3 line in Jeddah (~48/year, a contract around USD 5 billion).`),specs:{length:e(`11,0 m`,`11.0 m`),span:e(`20,5 m`,`20.5 m`),mtow:e(`4200 kg`,`4,200 kg`),payload:e(`480 kg, 6 węzłów`,`480 kg, 6 hardpoints`),speed:e(`370 km/h`,`370 km/h`),range:e(`4000 km (przelot)`,`4,000 km (ferry)`),endurance:e(`32 h`,`32 h`),ceiling:e(`9000 m`,`9,000 m`),engine:e(`WJ-9A, turbośmigłowy`,`WJ-9A turboprop`),guidance:e(`SATCOM, EO/IR`,`SATCOM, EO/IR`),launch:e(`pas startowy`,`runway`)}},{id:`ch4`,image:`/drones/ch4.jpg`,typeId:`isr-male`,domain:`air`,theaters:[`middle-east`,`africa`,`east-asia`,`global`],year:`2014–2026`,name:e(`CH-4 Rainbow`,`CH-4 Rainbow`),origin:e(`Chiny (CASC)`,`China (CASC)`),operators:e(`Irak, Arabia, Nigeria, Sudan i inni`,`Iraq, Saudi Arabia, Nigeria, Sudan and others`),role:e(`Tani MALE bez restrykcji zachodnich`,`Cheap MALE without Western restrictions`),note:e(`Odpowiedź CASC na Reapera w segmencie 1–2 mln USD. CH-4: 30–40 h, 345 kg. CH-5: do 60 h i ok. 1000 kg. Szeroko obecny w Iraku, Sahelu i Sudanie — tam, gdzie TB2 i Reaper są politycznie trudne.`,`CASC’s answer to the Reaper in the USD 1–2 million band. CH-4: 30–40 h, 345 kg. CH-5: up to 60 h and about 1,000 kg. Widely present in Iraq, the Sahel and Sudan — where TB2 and Reaper are politically hard.`),specs:{length:e(`8,5 m`,`8.5 m`),span:e(`18,0 m`,`18.0 m`),mtow:e(`1330 kg`,`1,330 kg`),payload:e(`345 kg (CH-4) / ~1000 kg (CH-5)`,`345 kg (CH-4) / ~1,000 kg (CH-5)`),speed:e(`210–235 km/h`,`210–235 km/h`),endurance:e(`30–40 h (CH-4) / do 60 h (CH-5)`,`30–40 h (CH-4) / up to 60 h (CH-5)`),ceiling:e(`7200–7500 m`,`7,200–7,500 m`),engine:e(`tłokowy / turbośmigłowy`,`piston / turboprop`),guidance:e(`LOS / SATCOM, EO/IR`,`LOS / SATCOM, EO/IR`),launch:e(`pas startowy`,`runway`),cost:e(`ok. 1–2 mln USD (CH-4)`,`about USD 1–2 million (CH-4)`)}},{id:`harop`,image:`/drones/harop2.jpg`,typeId:`loitering`,domain:`air`,theaters:[`middle-east`,`global`],year:`2010–2026`,name:e(`IAI Harop`,`IAI Harop`),origin:e(`Izrael (IAI)`,`Israel (IAI)`),operators:e(`Izrael, Azerbejdżan, Indie, inni`,`Israel, Azerbaijan, India, others`),role:e(`Amunicja krążąca antyradarowa`,`Anti-radiation loitering munition`),note:e(`Wzorzec amunicji krążącej. Seeker EO/IR i antyradiolokacyjny, operator w pętli. Górski Karabach 2020 — niszczenie OPL. Zasięg do 1000 km, czas lotu do 9 h. Droższy i rzadszy niż Lancet, ale z inną misją: tłumienie radarów.`,`The template of loitering munitions. EO/IR and anti-radiation seeker, operator in the loop. Nagorno-Karabakh 2020 — killing air defences. Range up to 1,000 km, endurance up to 9 h. Costlier and rarer than the Lancet, but a different mission: SEAD.`),specs:{length:e(`2,5 m`,`2.5 m`),span:e(`3,0 m`,`3.0 m`),mtow:e(`135 kg`,`135 kg`),warhead:e(`16–23 kg`,`16–23 kg`),speed:e(`do 417 km/h`,`up to 417 km/h`),cruise:e(`ok. 185 km/h`,`about 185 km/h`),range:e(`do 1000 km`,`up to 1,000 km`),endurance:e(`6–9 h`,`6–9 h`),engine:e(`UEL AR731, 37 KM`,`UEL AR731, 37 hp`),guidance:e(`EO/IR + antyradar, operator w pętli`,`EO/IR + anti-radiation, operator in the loop`),launch:e(`kontener / wyrzutnia`,`canister / launcher`)}},{id:`hermes900`,image:`/drones/hermes.jpg`,typeId:`isr-male`,domain:`air`,theaters:[`middle-east`,`africa`,`nato`],year:`2010–2026`,name:e(`Elbit Hermes 900`,`Elbit Hermes 900`),origin:e(`Izrael (Elbit)`,`Israel (Elbit)`),operators:e(`Izrael, Szwajcaria, Singapur, Libia i inni`,`Israel, Switzerland, Singapore, Libya and others`),role:e(`Izraelski workhorse MALE`,`Israel’s MALE workhorse`),note:e(`Gaza, Liban, Iran 2026 — podstawowy izraelski MALE. Do 36 h, ładunek 350 kg, wielosensorowy. Eksport do Europy i Azji. Heron TP (Eitan) jest większy i pełni rolę HALE.`,`Gaza, Lebanon, Iran 2026 — Israel’s baseline MALE. Up to 36 h, 350 kg payload, multi-sensor. Exported to Europe and Asia. Heron TP (Eitan) is larger and plays the HALE role.`),specs:{length:e(`8,3 m`,`8.3 m`),span:e(`15,0 m`,`15.0 m`),mtow:e(`1180 kg`,`1,180 kg`),payload:e(`350 kg ISR`,`350 kg ISR`),speed:e(`220 km/h`,`220 km/h`),endurance:e(`36 h`,`36 h`),ceiling:e(`9144 m (30 000 ft)`,`9,144 m (30,000 ft)`),engine:e(`Rotax 914, tłokowy`,`Rotax 914 piston`),guidance:e(`SATCOM, EO/IR, ELINT`,`SATCOM, EO/IR, ELINT`),launch:e(`pas startowy`,`runway`)}},{id:`mohajer6`,image:`/drones/mohajer.jpg`,typeId:`isr-male`,domain:`air`,theaters:[`middle-east`,`africa`],year:`2017–2026`,name:e(`Mohajer-6`,`Mohajer-6`),origin:e(`Iran (Qods)`,`Iran (Qods)`),operators:e(`Iran, proxy, Sudan (SAF), RF (ograniczenie)`,`Iran, proxies, Sudan (SAF), Russia (limited)`),role:e(`Irański MALE taktyczny`,`Iranian tactical MALE`),note:e(`Układ belka–dwa wysięgniki, do czterech pocisków Qaem/Almas. Czas lotu 12 h, zasięg 200 km. Eksport do Sudanu i osi oporu. W Ukrainie notowano zestrzelenia pojedynczych egzemplarzy używanych przez RF. Ababil — protoplasta wielu kamikaze Hezbollahu.`,`Pod-and-twin-boom, up to four Qaem/Almas missiles. Endurance 12 h, range 200 km. Exported to Sudan and the axis of resistance. In Ukraine, shoot-downs of isolated examples used by Russia have been logged. Ababil is the ancestor of many Hezbollah kamikaze drones.`),specs:{length:e(`ok. 7 m`,`about 7 m`),span:e(`10 m`,`10 m`),mtow:e(`600 kg`,`600 kg`),payload:e(`100 kg (4× Qaem/Almas + gimbal)`,`100 kg (4× Qaem/Almas + gimbal)`),speed:e(`200 km/h`,`200 km/h`),range:e(`200 km`,`200 km`),endurance:e(`12 h`,`12 h`),ceiling:e(`5400 m`,`5,400 m`),engine:e(`tłokowy, śmigło pchające`,`piston, pusher`),guidance:e(`LOS, EO/IR`,`LOS, EO/IR`),launch:e(`pas startowy`,`runway`)}},{id:`kizilelma`,image:`/drones/kizilelma.jpg`,typeId:`stealth-ucav`,domain:`air`,theaters:[`global`,`nato`],year:`2024–2026`,name:e(`Bayraktar Kızılelma`,`Bayraktar Kızılelma`),origin:e(`Turcja (Baykar)`,`Türkiye (Baykar)`),operators:e(`Turcja (wdrażanie)`,`Türkiye (entering service)`),role:e(`Myśliwiec bezzałogowy`,`Uncrewed fighter`),note:e(`Niskosygnałurowy odrzutowiec, radar AESA, zdolność pokładowa. MTOW 8,5 t, ładunek 1500 kg, Ma 0,9. Silnik ukraiński AI-25TLT / AI-322F, docelowo turecki TEI. W 2025 r. pierwsze odpalenie powietrze–powietrze. Nie jest dronem frontu ukraińskiego — to następna warstwa.`,`A low-observable jet, AESA radar, carrier-capable. MTOW 8.5 t, payload 1,500 kg, Mach 0.9. Ukrainian AI-25TLT / AI-322F engine, eventually Turkish TEI. In 2025 the first air-to-air shot. Not a Ukrainian-front drone — the next layer.`),specs:{length:e(`14,5 m`,`14.5 m`),span:e(`10,0 m`,`10.0 m`),mtow:e(`8500 kg`,`8,500 kg`),payload:e(`1500 kg`,`1,500 kg`),speed:e(`Ma 0,9 (ok. 1100 km/h)`,`Mach 0.9 (~1,100 km/h)`),range:e(`ok. 930 km`,`about 930 km`),endurance:e(`5 h`,`5 h`),ceiling:e(`13 700 m (45 000 ft)`,`13,700 m (45,000 ft)`),engine:e(`AI-25TLT / AI-322F (turbowentylator)`,`AI-25TLT / AI-322F turbofan`),guidance:e(`AESA, EO/IR, datalink`,`AESA, EO/IR, datalink`),launch:e(`pas / pokład`,`runway / deck`)}},{id:`gj11`,image:`/drones/gj11.jpg`,typeId:`stealth-ucav`,domain:`air`,theaters:[`east-asia`],year:`2019–2026`,name:e(`GJ-11 Sharp Sword`,`GJ-11 Sharp Sword`),aka:e(`Gongji-11, Mysterious Dragon`,`Gongji-11, Mysterious Dragon`),origin:e(`Chiny (Hongdu / Shenyang)`,`China (Hongdu / Shenyang)`),operators:e(`PLAAF (służba liniowa)`,`PLAAF (front-line service)`),role:e(`Stealth UCAV w służbie`,`Stealth UCAV in service`),note:e(`Jedyne skrzydło latające stealth UCAV faktycznie w służbie liniowej (szacunki otwarte). Zdjęcia w Tybecie 2025, teaming z J-20. Komora wewnętrzna na bomby i pociski. Morski GJ-21 na lotniskowcu Type 076 w próbach. Długość ok. 12,2 m, rozpiętość ok. 14 m — liczby szacunkowe.`,`The only stealth flying-wing UCAV actually in front-line service (open estimates). Photos in Tibet 2025, teaming with the J-20. Internal bay for bombs and missiles. A naval GJ-21 on the Type 076 carrier is on trials. Length about 12.2 m, span about 14 m — estimated.`),specs:{length:e(`ok. 12,2 m`,`about 12.2 m`),span:e(`ok. 14 m`,`about 14 m`),mtow:e(`szac. 10–20 t`,`est. 10–20 t`),payload:e(`komora wewnętrzna, szac. ~2000 kg`,`internal bay, est. ~2,000 kg`),speed:e(`wysokie poddźwiękowe`,`high subsonic`),range:e(`penetracja OPL (operacyjny)`,`AD penetration (operational)`),engine:e(`turbowentylator, dysza ekranowana`,`turbofan, shielded nozzle`),guidance:e(`stealth, datalink, teaming z J-20`,`stealth, datalink, J-20 teaming`),launch:e(`pas; GJ-21 — pokład`,`runway; GJ-21 — deck`)}},{id:`lucas`,image:`/drones/shahed.jpg`,typeId:`owa-deep`,domain:`air`,theaters:[`middle-east`,`nato`],year:`2026`,name:e(`LUCAS (FLM-136)`,`LUCAS (FLM-136)`),origin:e(`USA (SpektreWorks) — odwrotna inż. Shahed-136`,`USA (SpektreWorks) — reverse-engineered Shahed-136`),operators:e(`USA / CENTCOM`,`USA / CENTCOM`),role:e(`Amerykański tani OWA`,`American cheap OWA`),note:e(`Low-cost Uncrewed Combat Attack System. Pierwsze użycie bojowe 28 II 2026 przeciw Iranowi (operacja Epic Fury). Lżejszy od Shaheda (70–100 kg), głowica ok. 20 kg, zasięg ok. 800 km. Cel kosztowy 5–35 tys. USD. CENTCOM: „niezbędny”. Zachód przez cztery lata oglądał Gerany — LUCAS jest odpowiedzią produkcyjną.`,`Low-cost Uncrewed Combat Attack System. First combat use 28 Feb 2026 against Iran (Operation Epic Fury). Lighter than the Shahed (70–100 kg), warhead about 20 kg, range about 800 km. Cost target USD 5–35 thousand. CENTCOM: “essential”. The West watched Gerans for four years — LUCAS is the production answer.`),specs:{length:e(`ok. 3,0 m`,`about 3.0 m`),span:e(`ok. 2,4 m`,`about 2.4 m`),mtow:e(`70–100 kg`,`70–100 kg`),warhead:e(`ok. 20 kg, modularna`,`about 20 kg, modular`),speed:e(`150–185 km/h (nurkowanie 300)`,`150–185 km/h (dive 300)`),range:e(`ok. 800 km`,`about 800 km`),endurance:e(`4–6 h`,`4–6 h`),engine:e(`DA-215, 2-cyl. 215 cc`,`DA-215, 2-cyl 215 cc`),guidance:e(`GPS/INS, datalink, mesh MUSIC`,`GPS/INS, datalink, MUSIC mesh`),launch:e(`katapulta / RATO / pokład`,`catapult / RATO / deck`),cost:e(`ok. 35 tys. USD (cel 5 tys. przy skali)`,`about USD 35 thousand (USD 5k at scale)`)}},{id:`wiy-strila`,image:`/drones/strila.jpg`,typeId:`interceptor`,domain:`air`,theaters:[`ukraine`,`nato`],year:`2025–2026`,featured:!0,name:e(`WIY Striła`,`WIY Strila`),aka:e(`STRILA`,`STRILA`),origin:e(`Ukraina (WIY Drones)`,`Ukraine (WIY Drones)`),operators:e(`SZU, Gwardia Narodowa UA; zamówienie niemieckie`,`AFU, UA National Guard; German-funded order`),role:e(`Interceptor rakietowy przeciw Shahedom`,`Rocket-type interceptor against Shaheds`),tidbit:e(`W styczniu 2026 r. cena spadła z 3317 do 2292 dolarów — przez skalę i ukrainizację elektroniki (ok. 70% części krajowych). Niemcy sfinansowały 15 tys. sztuk dla Gwardii Narodowej.`,`In January 2026 the price fell from USD 3,317 to 2,292 — scale and a 70% Ukrainian electronics share. Germany funded 15,000 for the National Guard.`),note:e(`Flagowy interceptor kijowskiej firmy WIY. Wygląda jak mała rakieta, ale ma cztery wirniki: start niemal pionowy, wznoszenie 50 m/s, potem pościg. Prędkość maksymalna 350–415 km/h, pułap do 6 km, zasięg taktyczny 14–17 km (maks. 28–34 km). Głowica 500–700 g. Operator dostaje namiar z radaru, sam kończy atak po kontakcie wzrokowym — dzień i termowizja. Produkcja: około 100 sztuk dziennie. Wersja Striła 2 LR z przyspieszaczem stałopaliwowym i sztuczną inteligencją namierza cel nawet przy zagłuszaniu.`,`Flagship interceptor from Kyiv’s WIY. It looks like a small missile but has four rotors: near-vertical take-off, 50 m/s climb, then the chase. Top speed 350–415 km/h, ceiling 6 km, tactical reach 14–17 km (max 28–34 km). Warhead 500–700 g. Radar cues the operator, who finishes after visual contact — daylight and thermal. Output: about 100 a day. Strila 2 LR adds a solid booster and AI lock even under jamming.`),specs:{length:e(`550 mm (gotowy do lotu)`,`550 mm (ready to fly)`),span:e(`540 mm`,`540 mm`),mtow:e(`5,3–5,75 kg`,`5.3–5.75 kg`),warhead:e(`500–700 g`,`500–700 g`),speed:e(`350–415 km/h`,`350–415 km/h`),cruise:e(`150–200 km/h`,`150–200 km/h`),range:e(`14–17 km taktycznie; 28–34 km maks.`,`14–17 km tactical; 28–34 km max`),endurance:e(`12–15 min`,`12–15 min`),ceiling:e(`do 6000 m`,`up to 6,000 m`),engine:e(`4× silnik elektryczny, wznoszenie 50 m/s`,`4× electric, climb 50 m/s`),guidance:e(`radar + EO/IR, bez GPS w nowszych seriach`,`radar + EO/IR, GPS-denied in later series`),launch:e(`eVTOL / z ziemi, bez wyrzutni`,`eVTOL / from the ground, no rail`),cost:e(`2292 USD (I 2026; wcześniej 3317)`,`USD 2,292 (Jan 2026; previously 3,317)`)}},{id:`wiy-spys`,image:`/drones/strila.jpg`,typeId:`interceptor`,domain:`air`,theaters:[`ukraine`],year:`2026`,name:e(`WIY SPYS`,`WIY SPYS`),aka:e(`SPYS HL (z ręki)`,`SPYS HL (hand-launched)`),origin:e(`Ukraina (WIY Drones)`,`Ukraine (WIY Drones)`),operators:e(`SZU — pierwsze 50 sztuk na testy, VII 2026`,`AFU — first 50 for trials, Jul 2026`),role:e(`Interceptor przeciw odrzutowym Shahedom`,`Interceptor against jet Shaheds`),tidbit:e(`Celuje w cele lecące nawet 600 km/h. Silniki Motor-G i elektronika są ukraińskie — standardowe części nie wytrzymywały obciążeń.`,`It is built to catch targets flying at up to 600 km/h. Motor-G motors and the electronics are Ukrainian — off-the-shelf parts could not take the load.`),note:e(`Odpowiedź WIY na odrzutowe Gerany, które tłokowy interceptor często nie dogania. Prędkość przechwycenia do 600 km/h, zasięg 12 km, czas lotu 5 minut, głowica 300 g, pułap 6 km. Pierwsze sztuki mają system dościgania na kursie spotkaniowym — taki sam, jaki już działa na Strile. Wersja SPYS HL startuje z ręki, bez wyrzutni, i ma osłaniać kolumny oraz obiekty bez stałej infrastruktury. W lipcu 2026 r. wojsko dostało 50 egzemplarzy do testów bojowych; kodyfikacja po zebraniu statystyk.`,`WIY’s answer to jet Gerans that a piston interceptor often cannot catch. Engagement speed up to 600 km/h, range 12 km, five minutes in the air, 300 g warhead, ceiling 6 km. Early units home on a head-on course — the same trick already on Strila. SPYS HL is hand-launched, for columns and sites with no fixed kit. In July 2026 the army took 50 for combat trials; codification follows the statistics.`),specs:{warhead:e(`300 g`,`300 g`),speed:e(`przejęcie celu do 600 km/h`,`engagement up to 600 km/h`),range:e(`12 km`,`12 km`),endurance:e(`5 min`,`5 min`),ceiling:e(`6 km`,`6 km`),engine:e(`silniki ukraińskie Motor-G, elektronika WIY`,`Ukrainian Motor-G motors, WIY electronics`),guidance:e(`EO/IR + autonomiczne dościganie na kursie spotkaniowym`,`EO/IR + autonomous head-on homing`),launch:e(`z ziemi; SPYS HL — z ręki`,`from the ground; SPYS HL — by hand`)}},{id:`p1sun`,image:`/drones/p1sun.jpg`,typeId:`interceptor`,domain:`air`,theaters:[`ukraine`,`nato`,`middle-east`],year:`2025–2026`,featured:!0,name:e(`SkyFall P1-SUN`,`SkyFall P1-SUN`),aka:e(`P1-SUN Long / Jetkiller`,`P1-SUN Long / Jetkiller`),origin:e(`Ukraina (SkyFall)`,`Ukraine (SkyFall)`),operators:e(`SZU (m.in. 20. B. K-2, Kara-Dag); partnerstwo z Airbusem`,`AFU (incl. 20th Bde K-2, Kara-Dag); Airbus partnership`),role:e(`Najliczniejszy interceptor SkyFall`,`SkyFall’s most numerous interceptor`),tidbit:e(`Ukraińscy żołnierze przezwali go „Pisun” — od zapisu P1-SUN. Firma twierdzi, że rodzina zestrzeliła ponad 10 tys. rosyjskich bezzałogowców; sam P1-SUN — ponad 3 tys. Shahedów w 2026 r.`,`Ukrainian soldiers nicknamed it “Pisun” — from the spelling P1-SUN. The firm claims the family has downed over 10,000 Russian UAVs; P1-SUN itself more than 3,000 Shaheds in 2026.`),note:e(`Czarna „rakietka” z czterema wirnikami, sterowana nawet przez internet z drugiego kraju. Bazowo: 300–310 km/h, 15–23 km, pułap 5 km, głowica 800 g, koszt około 1000 dolarów. Wersja Long (Eurosatory 2026) podwaja zasięg do 33 km i pułap do 9 km, z pokładową SI namierzającą cel. Jetkiller (Farnborough 2026) rozpędza się do 370 km/h i ma łapać odrzutowe Shahedy w momentach, gdy zwalniają — w testach bojowych zniszczył ponad tuzin takich celów. SkyFall zapowiadał 50 tys. sztuk miesięcznie. W czerwcu 2026 r. umowa z Airbusem pod kątem europejskiej tarczy nieba. Start także z An-28 i ze śmigłowców.`,`A black four-rotor “dart”, flown even over the internet from another country. Baseline: 300–310 km/h, 15–23 km, ceiling 5 km, 800 g warhead, about USD 1,000. The Long (Eurosatory 2026) doubles reach to 33 km and ceiling to 9 km, with onboard AI lock. Jetkiller (Farnborough 2026) hits 370 km/h and is meant to catch jet Shaheds when they throttle back — combat trials claimed a dozen-plus such kills. SkyFall talked of 50,000 a month. In June 2026 a deal with Airbus for Europe’s sky shield. Also launched from An-28s and helicopters.`),specs:{length:e(`ok. 50–60 cm (kadłub-pocisk)`,`about 50–60 cm (dart fuselage)`),warhead:e(`800 g`,`800 g`),speed:e(`300–310 km/h; Jetkiller 370 km/h`,`300–310 km/h; Jetkiller 370 km/h`),range:e(`15–23 km; Long 33 km`,`15–23 km; Long 33 km`),endurance:e(`14–17 min`,`14–17 min`),ceiling:e(`5 km; Long do 9 km`,`5 km; Long up to 9 km`),engine:e(`4× silnik elektryczny, konstrukcja modułowa`,`4× electric, modular airframe`),guidance:e(`FPV + SI (Long); sterowanie przez sieć`,`FPV + AI (Long); network control`),launch:e(`z ręki / z ziemi / z An-28 / ze śmigłowca`,`hand / ground / An-28 / helicopter`),cost:e(`ok. 1000 USD (baza)`,`about USD 1,000 (baseline)`)}},{id:`luckystrike2`,image:`/drones/vampire.jpg`,typeId:`isr-cots`,domain:`air`,theaters:[`ukraine`],year:`2025–2026`,name:e(`PG Robotics Lucky Strike-2`,`PG Robotics Lucky Strike-2`),origin:e(`Ukraina (PG Robotics, Kijów)`,`Ukraine (PG Robotics, Kyiv)`),operators:e(`Siły Zbrojne Ukrainy`,`Armed Forces of Ukraine`),role:e(`Zwiad i uderzenie tam, gdzie Mavic traci łączność`,`ISR and strike where a Mavic loses the link`),tidbit:e(`Jeden z pierwszych ukraińskich kompleksów, który przeszedł pełną kodyfikację NATO. Komplet — pięć burt, stacja, antena, komputer, plecak — kosztuje 1,5–2 mln hrywien.`,`One of the first Ukrainian complexes to complete full NATO codification. A set — five airframes, station, antenna, computer, pack — costs UAH 1.5–2 million.`),note:e(`Kijowska PG Robotics buduje wielowirnikowce pod walkę radioelektroniczną, nie pod pokaz. Lucky Strike-2 ma zastąpić Mavica w zwiadzie: do 46 minut w powietrzu, 3 kg ładunku, 15 km, łączność z przeskakiwaniem częstotliwości (PPRCZ) — gdy wróg tłumi jeden kanał, system skacze na drugi. Trzy wersje: DN (dzień + termowizja), DD (zoom cyfrowy), DO (zoom optyczny 30×). Wariant 2.1 sam wraca po utracie GPS. Firma prowadzi też szkolenie operatorów od podstaw do zastosowania bojowego.`,`Kyiv’s PG Robotics builds multirotors for electronic warfare, not for the show stand. Lucky Strike-2 is meant to replace the Mavic in scouting: up to 46 minutes, 3 kg payload, 15 km, frequency-hopping — if one channel is jammed, it jumps. Three fits: DN (day + thermal), DD (digital zoom), DO (30× optical). Version 2.1 returns by itself after GPS loss. The firm also trains operators from basics to combat use.`),specs:{payload:e(`do 3 kg`,`up to 3 kg`),speed:e(`do 80 km/h`,`up to 80 km/h`),range:e(`do 15 km`,`up to 15 km`),endurance:e(`do 46 min`,`up to 46 min`),engine:e(`wielowirnikowiec elektryczny`,`electric multirotor`),guidance:e(`PPRCZ (FHSS), dzień / termowizja / zoom 30×`,`FHSS, day / thermal / 30× zoom`),cost:e(`kompleks 1,5–2 mln UAH (5 burt)`,`UAH 1.5–2 m per complex (5 airframes)`)}},{id:`luckystrike15`,image:`/drones/vampire2.jpg`,typeId:`bomber`,domain:`air`,theaters:[`ukraine`],year:`2023–2026`,name:e(`PG Robotics Lucky Strike-1.5`,`PG Robotics Lucky Strike-1.5`),origin:e(`Ukraina (PG Robotics)`,`Ukraine (PG Robotics)`),operators:e(`Siły Zbrojne Ukrainy`,`Armed Forces of Ukraine`),role:e(`Dzienny bombowiec i minowanie zdalne`,`Day bomber and remote mining`),tidbit:e(`Jeden egzemplarz serii Lucky Strike odbywa średnio 50–70 wylotów; rekord to 135. To nie kamikaze — to oszczędny robot.`,`One Lucky Strike airframe averages 50–70 sorties; the record is 135. Not a kamikaze — a thrifty robot.`),note:e(`Ulepszony bombowiec dzienny na bazie Lucky Strike-1, który lata od 2023 r. Ładunek do 4 kg, zasięg 10–17 km zależnie od masy, czas lotu 20–50 minut. Trzy węzły podwieszeń. Służy do zrzutu, minowania zdalnego, noszenia przekaźników, ataku na krążące drony przeciwnika i odnajdywania zestrzelonych maszyn. Producent zapowiada wersję nocną i mocniejszy wideolink. Tańszy w eksploatacji niż jednorazowe FPV, bo wraca.`,`An upgraded day bomber from the Lucky Strike-1, flying since 2023. Payload up to 4 kg, 10–17 km depending on load, 20–50 minutes in the air. Three hardpoints. Used for drops, remote mining, carrying relays, attacking enemy loitering drones and recovering downed machines. The maker promises a night version and a stronger video link. Cheaper to run than one-way FPV, because it comes home.`),specs:{payload:e(`do 4 kg`,`up to 4 kg`),speed:e(`do 100 km/h`,`up to 100 km/h`),range:e(`10–17 km (zależnie od ładunku)`,`10–17 km (load-dependent)`),endurance:e(`20–50 min`,`20–50 min`),engine:e(`wielowirnikowiec elektryczny`,`electric multirotor`),guidance:e(`radio cyfrowe, operator w pętli`,`digital radio, operator in the loop`),launch:e(`z ziemi, wielorazowy`,`from the ground, reusable`)}},{id:`luckyshot`,image:`/drones/fpv.jpg`,typeId:`fpv-radio`,domain:`air`,theaters:[`ukraine`],year:`2024–2026`,name:e(`PG Robotics LuckyShot`,`PG Robotics LuckyShot`),origin:e(`Ukraina (PG Robotics)`,`Ukraine (PG Robotics)`),operators:e(`Siły Zbrojne Ukrainy`,`Armed Forces of Ukraine`),role:e(`Stabilizowany kamikaze 10-calowy`,`Stabilised 10-inch kamikaze`),note:e(`Skodyfikowany (kod NATO) 10-calowy FPV z ramą karbonową i automatycznym dościganiem w fazie końcowej. Zasięg lotu do 20 km, taktyczny promień 15 km, ładunek 1,5 kg, prędkość z ładunkiem 100 km/h (przelot 60). Pułap roboczy do 500 m. Wideo i sterowanie na cyfrowym kanale 1,6–2,7 GHz z przeskakiwaniem częstotliwości. Ma być wpięty w ten sam interfejs co Lucky Strike, żeby zwiad i kamikaze obsługiwał jeden zestaw.`,`A NATO-codified 10-inch FPV with a carbon frame and automatic terminal homing. Flight range 20 km, tactical radius 15 km, 1.5 kg payload, 100 km/h laden (cruise 60). Working ceiling 500 m. Digital video and control on 1.6–2.7 GHz with frequency hopping. Meant to share the Lucky Strike interface, so scout and kamikaze run from one set.`),specs:{span:e(`rama 10″, karbon`,`10″ carbon frame`),payload:e(`1,5 kg`,`1.5 kg`),speed:e(`100 km/h z ładunkiem; przelot 60 km/h`,`100 km/h laden; cruise 60 km/h`),range:e(`20 km lotu / 15 km taktycznie`,`20 km flight / 15 km tactical`),ceiling:e(`do 500 m`,`up to 500 m`),engine:e(`4× bezszczotkowy, pakiet 13500 mAh`,`4× brushless, 13,500 mAh pack`),guidance:e(`wideo cyfrowe 1,6–2,7 GHz, auto-dościganie`,`digital video 1.6–2.7 GHz, auto-homing`)}},{id:`bober`,image:`/drones/bober.jpg`,typeId:`owa-deep`,domain:`air`,theaters:[`ukraine`],year:`2023–2026`,name:e(`UJ-26 Bóbr`,`UJ-26 Bober`),aka:e(`Beaver`,`Beaver`),origin:e(`Ukraina (GUR / przemysł krajowy)`,`Ukraine (HUR / domestic industry)`),operators:e(`GUR, Siły Zbrojne Ukrainy`,`HUR, Armed Forces of Ukraine`),role:e(`Wczesny deep-strike na rafinerie`,`Early deep-strike on refineries`),tidbit:e(`Układ kaczka i pchające śmigło. Leci tuż nad drzewami, bez tethersu do operatora — nie ma czego zagłuszać. Stąd trafienia w farmy zbiorników, nie w pojedynczy pojazd.`,`Canards and a pusher propeller. It flies just above the trees with no operator tether — nothing to jam. Hence tank farms, not a single truck.`),note:e(`Jeden z pierwszych ukraińskich dronów dalekiego zasięgu, które regularnie latały w głąb Rosji. Kadłub jak ultralekki samolot, ładunek 20–50 kg (bywają kumulacyjne KZ-6), zasięg rzędu 800–1000 km, koszt około 50 tys. dolarów. Naprowadzanie INS/GNSS po punktach, bez operatora w pętli — mniej celny niż FPV, za to odporny na WRE. GUR używał go m.in. przeciw rafineriom w Riazaniu, Saratowie i Niżnym Nowogrodzie.`,`One of the first Ukrainian long-range drones to fly regularly into Russia. Ultralight-like airframe, 20–50 kg warhead (some KZ-6 shaped charges), about 800–1,000 km, around USD 50 thousand. INS/GNSS waypoints, no operator in the loop — less precise than FPV, but hard to jam. HUR used it against refineries in Ryazan, Saratov and Nizhny Novgorod.`),specs:{span:e(`ok. 3–4 m`,`about 3–4 m`),warhead:e(`20–50 kg (m.in. KZ-6)`,`20–50 kg (incl. KZ-6)`),speed:e(`100–150 km/h`,`100–150 km/h`),range:e(`800–1000 km`,`800–1,000 km`),engine:e(`tłokowy, śmigło pchające, układ kaczka`,`piston, pusher, canard layout`),guidance:e(`INS/GNSS, bez operatora w pętli`,`INS/GNSS, no operator in the loop`),cost:e(`ok. 50 tys. USD`,`about USD 50 thousand`)}},{id:`v2u`,image:`/drones/v2u.jpg`,typeId:`loitering`,domain:`air`,theaters:[`ukraine`],year:`2025–2026`,name:e(`V2U`,`V2U`),origin:e(`Rosja`,`Russia`),operators:e(`Siły Zbrojne Federacji Rosyjskiej`,`Armed Forces of the Russian Federation`),role:e(`Autonomiczna amunicja krążąca z SI`,`Autonomous AI loitering munition`),tidbit:e(`Późne egzemplarze odzyskane w 2025 r. nie miały radia w ogóle. CSIS ocenia, że Rosja wystawiła w boju w pełni autonomiczną broń — nie ma czego zagłuszać.`,`Late 2025 recoveries had no radio at all. CSIS assesses that Russia has fielded a fully autonomous weapon — there is nothing to jam.`),note:e(`Rosyjski dron uderzeniowy z komputerem Nvidia Jetson i nawigacją po rzeźbie terenu. Rozpiętość około 1,2 m, zasięg rzędu 50 km. Nie jest szybki — idzie o to, by sam znalazł cel na zdjęciu, bez operatora. To inna szkoła niż Lancet (człowiek w pętli) i inna niż FPV światłowodowe (kabel). Na froncie 2026 r. pojawia się obok masowych tanich FPV jako warstwa „odporna na WRE przez brak łączności”.`,`A Russian strike drone with an Nvidia Jetson and terrain-matching navigation. Wingspan about 1.2 m, range around 50 km. It is not fast — the point is to find the target in a picture, with no operator. A different school from the Lancet (human in the loop) and from fibre FPV (a cable). In 2026 it appears beside mass cheap FPV as the layer that is EW-proof because it has no link.`),specs:{span:e(`ok. 1,2 m`,`about 1.2 m`),speed:e(`ok. 60–80 km/h (szacunki)`,`about 60–80 km/h (estimates)`),range:e(`ok. 50 km`,`about 50 km`),engine:e(`elektryczny, stałopłat`,`electric, fixed-wing`),guidance:e(`SI (Jetson), matching terenu; nowsze — bez radia`,`AI (Jetson), terrain matching; later — no radio`)}},{id:`kargu`,image:`/drones/kargu.jpg`,typeId:`loitering`,domain:`air`,theaters:[`middle-east`,`africa`,`global`],year:`2020–2026`,name:e(`STM KARGU`,`STM KARGU`),origin:e(`Turcja (STM)`,`Turkey (STM)`),operators:e(`Turcja i odbiorcy eksportowi (Libia, Syria, Sahel)`,`Turkey and export clients (Libya, Syria, Sahel)`),role:e(`Rotacyjny kamikaze z funkcjami roju`,`Rotary kamikaze with swarm features`),tidbit:e(`Jeden z nielicznych seryjnych „dronów-zabójców” z namierzaniem twarzy i trybem roju, o którym głośno było jeszcze przed pełnoskalową wojną w Ukrainie.`,`One of the few production “killer drones” with face-cueing and a swarm mode, famous even before the full-scale war in Ukraine.`),note:e(`Czterowirnikowiec-kamikaze piechoty. Zasięg około 10 km, ładunek 1,4–1,5 kg (odłamkowy albo przeciwpancerny), czas lotu do 30 minut. Operator może odwołać atak. STM chwali się trybem roju i automatycznym rozpoznawaniem celów. Używany w Libii i Syrii; na ukraińskim froncie nie jest masowy — tam króluje tańsze FPV. Pokazuje, jak wyglądała amunicja krążąca „z półki NATO-eksportera” zanim wojna wymusiła konstrukcje za kilkaset dolarów.`,`An infantry quadcopter kamikaze. About 10 km, 1.4–1.5 kg warhead (HE or anti-armour), up to 30 minutes. The operator can abort. STM advertises a swarm mode and automatic target recognition. Used in Libya and Syria; not massed on the Ukrainian front — cheaper FPV rules there. It shows what “NATO-exporter shelf” loitering munitions looked like before the war forced designs at a few hundred dollars.`),specs:{mtow:e(`ok. 7 kg`,`about 7 kg`),warhead:e(`1,4–1,5 kg (HE / ppanc.)`,`1.4–1.5 kg (HE / anti-armour)`),speed:e(`ok. 144 km/h`,`about 144 km/h`),range:e(`ok. 10 km`,`about 10 km`),endurance:e(`do 30 min`,`up to 30 min`),engine:e(`4× silnik elektryczny`,`4× electric motors`),guidance:e(`EO + SI, operator może odwołać`,`EO + AI, operator can abort`)}},{id:`hero120`,image:`/drones/warmate.jpg`,typeId:`loitering`,domain:`air`,theaters:[`middle-east`,`nato`,`global`],year:`2017–2026`,name:e(`UVision Hero-120`,`UVision Hero-120`),origin:e(`Izrael (UVision)`,`Israel (UVision)`),operators:e(`Izrael, USMC i inni`,`Israel, USMC and others`),role:e(`Amunicja krążąca średniego kalibru`,`Medium-calibre loitering munition`),note:e(`Izraelska amunicja krążąca „plecakowa plus”: masa około 12–15 kg, głowica 4,5 kg, zasięg 40–60 km, czas lotu do godziny. Start z wyrzutni rurowej. Większa od Warmate i Switchblade’a 300, tańsza i lżejsza od Switchblade’a 600. Pokazuje zachodnią szkołę: jeden precyzyjny pocisk zamiast roju tanich FPV. Na Ukrainie nie jest masowa — za droga na wojnę na wyczerpanie.`,`An Israeli “rucksack-plus” loitering munition: about 12–15 kg, 4.5 kg warhead, 40–60 km, up to an hour. Tube launch. Larger than Warmate and Switchblade 300, cheaper and lighter than Switchblade 600. The Western school: one precise round rather than a swarm of cheap FPV. Not massed in Ukraine — too dear for a war of attrition.`),specs:{mtow:e(`ok. 12–15 kg`,`about 12–15 kg`),warhead:e(`4,5 kg`,`4.5 kg`),range:e(`40–60 km`,`40–60 km`),endurance:e(`do 60 min`,`up to 60 min`),engine:e(`elektryczny, stałopłat`,`electric, fixed-wing`),guidance:e(`EO/IR, operator w pętli`,`EO/IR, operator in the loop`),launch:e(`wyrzutnia rurowa`,`tube launcher`)}},{id:`merops`,image:`/drones/ram2x.jpg`,typeId:`interceptor`,domain:`air`,theaters:[`ukraine`,`nato`,`middle-east`],year:`2024–2026`,name:e(`Merops (Surveyor)`,`Merops (Surveyor)`),origin:e(`USA (Perennial Autonomy)`,`USA (Perennial Autonomy)`),operators:e(`SZU; Armia USA — zamówienie ok. 13 tys.`,`AFU; US Army — order ~13,000`),role:e(`Amerykański interceptor ze spadochronem`,`US interceptor with a parachute`),tidbit:e(`Jeśli spudłuje, wraca na spadochronie. Jeden z niewielu interceptorów, który nie musi być jednorazowy. Armia USA kupiła około 13 tysięcy.`,`If it misses, it comes back on a parachute. One of the few interceptors that need not be expendable. The US Army bought about 13,000.`),note:e(`System Erica Schmidta: stacja, wyrzutnie i stałopłaty Surveyor ze skrzydłem i usterzeniem w X. Prędkość ponad 280 km/h, sztuczna inteligencja prowadzi, gdy GPS i radio padną. Koszt kompleksu 14–15 tys. dolarów, przy dużych zamówieniach spada. W Ukrainie od 2024 r.; amerykański sekretarz armii chwalił skuteczność. Startowano je także z An-28 razem z P1-SUN — pierwszy taki tandem przeciw Shahedom. Inna filozofia niż Sting i Striła: droższy, za to odzyskiwalny.`,`Eric Schmidt’s system: a station, launchers and Surveyor monoplanes with an X-tail. Speed above 280 km/h; AI flies when GPS and radio die. A complex costs USD 14–15 thousand, less in bulk. In Ukraine since 2024; the US Army secretary praised the results. Also launched from An-28s with P1-SUNs — the first such pairing against Shaheds. A different school from Sting and Strila: dearer, but recoverable.`),specs:{speed:e(`>280 km/h`,`>280 km/h`),range:e(`strefa OPL (dane niejawne)`,`AD zone (figures withheld)`),engine:e(`stałopłat, usterzenie w X`,`fixed-wing, X-tail`),guidance:e(`SI + operator; praca w WRE`,`AI + operator; works under EW`),launch:e(`wyrzutnia; odzysk spadochronem`,`launcher; parachute recovery`),cost:e(`14–15 tys. USD za kompleks`,`USD 14–15 thousand per complex`)}},{id:`aq400`,image:`/drones/fp1.jpg`,typeId:`owa-deep`,domain:`air`,theaters:[`ukraine`],year:`2024–2026`,name:e(`AQ-400 Scythe`,`AQ-400 Scythe`),origin:e(`Ukraina (Terminal Autonomy)`,`Ukraine (Terminal Autonomy)`),operators:e(`Siły Zbrojne Ukrainy`,`Armed Forces of Ukraine`),role:e(`Tani deep-strike ze skrzydłem tandemowym`,`Cheap deep-strike with tandem wings`),note:e(`Ochotniczy projekt, który wszedł do serii. Kadłub jak skrzynka, skrzydła tandemowe z płytami na końcówkach — wygląda prymitywnie i ma taki być. Zasięg około 750 km przy głowicy 32 kg; przy 70 kg zasięg spada. INS/GNSS, opcjonalnie kamera i operator, gdy jest łączność. Tańszy i prostszy niż Liutyj, cięższy w ładunku niż wczesny Bóbr. Pokazuje ukraińską szkołę „sklejki i piany”: byle leciało i wybuchło we właściwym miejscu.`,`A volunteer project that went into series. Box fuselage, tandem wings with endplates — it looks crude, and is meant to. About 750 km with a 32 kg warhead; range falls at 70 kg. INS/GNSS, optional camera and operator when a link exists. Cheaper and simpler than Liutyi, heavier in payload than the early Bober. The Ukrainian school of “plywood and foam”: so long as it flies and goes off in the right place.`),specs:{warhead:e(`32 kg (do 70 kg kosztem zasięgu)`,`32 kg (up to 70 kg at the expense of range)`),range:e(`ok. 750 km`,`about 750 km`),engine:e(`tłokowy, skrzydło tandemowe`,`piston, tandem wing`),guidance:e(`INS/GNSS, opcjonalnie EO i operator`,`INS/GNSS, optional EO and operator`),launch:e(`wózek / szyna / podwozie`,`dolly / rail / undercarriage`)}}];function i(e){return r.find(t=>t.id===e)}function a(e){return r.filter(t=>t.typeId===e)}function o(){return[`shahed136`,`tb2`,`p1sun`,`wiy-strila`,`lancet`,`fp1`,`liutyi`,`vampire`,`magura-v5`,`mq9`,`palianytsia`,`orlan10`].map(i).filter(e=>!!e)}var s=[{id:`fpv-radio`,name:{pl:`FPV kamikaze (radiowe)`,en:`FPV kamikaze (radio)`},short:{pl:`FPV`,en:`FPV`},domain:`air`,range:{pl:`5–25 km`,en:`5–25 km`},role:{pl:`Precyzyjny atak na piechotę, okopy i pojazdy w strefie kontaktu. Najliczniejsza klasa wojny dronowej.`,en:`Precision attack on infantry, trenches and vehicles in the contact zone. The most numerous class of the drone war.`}},{id:`fpv-fiber`,name:{pl:`FPV światłowodowe`,en:`Fibre-optic FPV`},short:{pl:`Światłowód`,en:`Fibre`},domain:`air`,range:{pl:`15–65 km`,en:`15–65 km`},role:{pl:`Odporne na zagłuszanie. Na początku 2026 r. typowy zasięg 15–25 km; później 40–50 km, po stronie rosyjskiej nawet ok. 65 km.`,en:`Jam-resistant. Early 2026 typical reach 15–25 km; later 40–50 km, on the Russian side up to about 65 km.`}},{id:`fpv-wing`,name:{pl:`FPV skrzydłowe`,en:`Fixed-wing FPV`},short:{pl:`Skrzydło`,en:`Wing`},domain:`air`,range:{pl:`25–100 km`,en:`25–100 km`},role:{pl:`Skrzydło zamiast wirników: większy ładunek i zasięg, inna sygnatura radiowa. Przykład: rosyjska Mołnija-2.`,en:`A wing instead of rotors: more payload and range, a different radio signature. Example: Russia’s Molniya-2.`}},{id:`bomber`,name:{pl:`Ciężkie bombowce wielowirnikowe`,en:`Heavy multirotor bombers`},short:{pl:`Baba Jaga`,en:`Baba Yaga`},domain:`air`,range:{pl:`10–20 km`,en:`10–20 km`},role:{pl:`Sześcio- i ośmiowirnikowce zrzucające miny i pociski moździerzowe (10–15 kg i więcej), głównie nocą. Latają wielokrotnie. Vampire (SkyFall), Lucky Strike (PG Robotics).`,en:`Hexa- and octocopters dropping mines and mortar rounds (10–15+ kg), mostly at night. Reusable. Vampire (SkyFall), Lucky Strike (PG Robotics).`}},{id:`isr-cots`,name:{pl:`ISR komercyjne`,en:`Commercial ISR`},short:{pl:`COTS`,en:`COTS`},domain:`air`,range:{pl:`3–15 km`,en:`3–15 km`},role:{pl:`DJI Mavic, Autel i pochodne — korekta ognia artylerii, rozpoznanie bliskie, „oczy” drużyny.`,en:`DJI Mavic, Autel and derivatives — artillery adjustment, close reconnaissance, the squad’s eyes.`}},{id:`isr-tactical`,name:{pl:`ISR taktyczne skrzydłowe`,en:`Tactical fixed-wing ISR`},short:{pl:`ISR taktyczne`,en:`Tactical ISR`},domain:`air`,range:{pl:`40–300 km`,en:`40–300 km`},role:{pl:`Godziny w powietrzu, termowizja, naprowadzanie ognia. Shark, Leleka, Furia, Orlan-10.`,en:`Hours on station, thermal imagers, fire direction. Shark, Leleka, Furia, Orlan-10.`}},{id:`isr-male`,name:{pl:`MALE / HALE / UCAV`,en:`MALE / HALE / UCAV`},short:{pl:`MALE`,en:`MALE`},domain:`air`,range:{pl:`setki–tysiące km`,en:`hundreds–thousands of km`},role:{pl:`Długotrwałe rozpoznanie i uzbrojone patrole: TB2, Akıncı, Reaper, Wing Loong, Hermes 900.`,en:`Persistent reconnaissance and armed patrols: TB2, Akıncı, Reaper, Wing Loong, Hermes 900.`}},{id:`loitering`,name:{pl:`Amunicja krążąca`,en:`Loitering munitions`},short:{pl:`Krążąca`,en:`Loitering`},domain:`air`,range:{pl:`10–90 km`,en:`10–90 km`},role:{pl:`Czeka nad rejonem, atakuje po identyfikacji. Lancet, Switchblade, RAM-2X, Warmate, Harop.`,en:`Holds over an area, then dives after identification. Lancet, Switchblade, RAM-2X, Warmate, Harop.`}},{id:`owa-mid`,name:{pl:`Uderzenie średniego zasięgu`,en:`Medium-range strike`},short:{pl:`Średni zasięg`,en:`Mid-strike`},domain:`air`,range:{pl:`50–500 km`,en:`50–500 km`},role:{pl:`Most między FPV a uderzeniem w głąb. FP-2, RAM-2X — logistyka i OPL na zapleczu.`,en:`The bridge between FPV and deep strike. FP-2, RAM-2X — logistics and air defences in the rear.`}},{id:`owa-deep`,name:{pl:`Uderzenie w głąb (OWA)`,en:`Deep-strike / OWA`},short:{pl:`Głębokie`,en:`Deep strike`},domain:`air`,range:{pl:`500–3000+ km`,en:`500–3,000+ km`},role:{pl:`Jednokierunkowe uderzenia w głąb: Shahed/Geran, Liutyj, FP-1, Flamingo.`,en:`One-way attacks into the deep rear: Shahed/Geran, Liutyi, FP-1, Flamingo.`}},{id:`jet-drone`,name:{pl:`Drony odrzutowe i rakietodrony`,en:`Jet drones and missile-drones`},short:{pl:`Odrzut`,en:`Jet`},domain:`air`,range:{pl:`300–1000+ km`,en:`300–1,000+ km`},role:{pl:`Prędkość 400–800+ km/h. Geran-3, Palianytsia, Pekło — trudniejsze do przechwycenia.`,en:`400–800+ km/h. Geran-3, Palianytsia, Peklo — harder to intercept.`}},{id:`interceptor`,name:{pl:`Drony przechwytujące`,en:`Interceptor drones`},short:{pl:`Interceptor`,en:`Interceptor`},domain:`air`,range:{pl:`lokalny / pułap 3–9 km`,en:`local / 3–9 km ceiling`},role:{pl:`Tania odpowiedź na Shahedy i zwiadowców. WIY Striła i SPYS, SkyFall P1-SUN, Sting (Wild Hornets) — zwykle 1–3 tys. dolarów za sztukę.`,en:`A cheap answer to Shaheds and scouts. WIY Strila and SPYS, SkyFall P1-SUN, Sting (Wild Hornets) — usually USD 1–3 thousand apiece.`}},{id:`decoy`,name:{pl:`Wabiki`,en:`Decoys`},short:{pl:`Wabik`,en:`Decoy`},domain:`air`,range:{pl:`zależnie od salwy`,en:`salvo-dependent`},role:{pl:`Gerbera — saturacja obrony przeciwlotniczej tanim skrzydłem z pianki, czasem z małą głowicą.`,en:`Gerbera — saturating air defences with a cheap foam wing, sometimes carrying a small warhead.`}},{id:`usv`,name:{pl:`Bezzałogowce nawodne`,en:`Uncrewed surface vessels`},short:{pl:`USV`,en:`USV`},domain:`sea`,range:{pl:`800–1500 km`,en:`800–1,500 km`},role:{pl:`Magura, Sea Baby — ataki na flotę i mosty, start Shahedów znad morza, rakiety z pokładu.`,en:`Magura, Sea Baby — attacks on fleets and bridges, Shahed launches from the sea, missiles from the deck.`}},{id:`ugv`,name:{pl:`Roboty naziemne`,en:`Uncrewed ground vehicles`},short:{pl:`UGV`,en:`UGV`},domain:`ground`,range:{pl:`3–12 km`,en:`3–12 km`},role:{pl:`Logistyka, ewakuacja, minowanie, szturm. Ukraina: 16,6 tys. misji w czerwcu 2026 r.`,en:`Logistics, casualty evacuation, mining, assault. Ukraine: 16,600 missions in June 2026.`}},{id:`stealth-ucav`,name:{pl:`Stealth UCAV`,en:`Stealth UCAV`},short:{pl:`Stealth`,en:`Stealth`},domain:`air`,range:{pl:`operacyjny / strategiczny`,en:`operational / strategic`},role:{pl:`Niskosygnałurowe skrzydła latające: chiński GJ-11, turecki Kızılelma.`,en:`Low-observable flying wings: China’s GJ-11, Turkey’s Kızılelma.`}}],c=[{id:`ukraine`,name:{pl:`Front ukraiński`,en:`Ukrainian front`},blurb:{pl:`Laboratorium wojny dronowej. Miliony FPV, nocne salwy Geranów, interceptory WIY i SkyFall, kutry bezzałogowe na Morzu Czarnym.`,en:`The laboratory of drone warfare. Millions of FPV, nightly Geran salvos, WIY and SkyFall interceptors, uncrewed boats on the Black Sea.`}},{id:`middle-east`,name:{pl:`Bliski Wschód`,en:`Middle East`},blurb:{pl:`Rodzina Shahed, Harop, FPV Hezbollahu, Huti przeciw MQ-9, wojna w Zatoce 2026.`,en:`The Shahed family, Harop, Hezbollah FPV, Houthis versus the MQ-9, the 2026 Gulf war.`}},{id:`africa`,name:{pl:`Afryka`,en:`Africa`},blurb:{pl:`Sudan, Sahel, Libia, Kongo: TB2, Akıncı, Wing Loong, CH-4, irańskie Mohajer.`,en:`Sudan, the Sahel, Libya, Congo: TB2, Akıncı, Wing Loong, CH-4, Iranian Mohajer.`}},{id:`east-asia`,name:{pl:`Azja Wschodnia`,en:`East Asia`},blurb:{pl:`Chiny: GJ-11, Wing Loong, WZ-7. Tajwan ćwiczy „hellscape” na wzór Ukrainy.`,en:`China: GJ-11, Wing Loong, WZ-7. Taiwan rehearses a Ukraine-style “hellscape”.`}},{id:`nato`,name:{pl:`NATO i USA`,en:`NATO and the USA`},blurb:{pl:`Reaper, Switchblade, program Gauntlet/LASSO, amerykański LUCAS (odwrotna inżynieria Shaheda).`,en:`Reaper, Switchblade, Gauntlet/LASSO, the US LUCAS (a reverse-engineered Shahed).`}},{id:`global`,name:{pl:`Eksport i proliferacja`,en:`Export and proliferation`},blurb:{pl:`Turcja, Chiny, Iran i Izrael jako dostawcy. Wojna w Ukrainie przyspieszyła kopiowanie tanich OWA.`,en:`Turkey, China, Iran and Israel as suppliers. The war in Ukraine sped up copying of cheap OWA drones.`}}],l={air:{pl:`Powietrze`,en:`Air`},sea:{pl:`Morze`,en:`Sea`},ground:{pl:`Ląd`,en:`Ground`}};export{n as a,o as c,r as i,i as l,c as n,t as o,s as r,a as s,l as t};